quests[53717] = { id = 53717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Hochland halten" }
quests[53719] = { id = 53719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefolgschaft der Zandalari", description = "Die Entscheidung is' gefall'n, {name}.\n\nDie Zandalari werd'n sich der Horde anschließ'n.\n\nUnser gemeinsamer Weg war lang und schwierig. Gemeinsam haben wir viele Verluste erlitt'n. Die Horde hat Opfer für die Zandalari gebracht un' umgekehrt. Diese Hingabe kann ich nur durch unsre Loyalität ehr'n.\n\nHolt Euern Kriegshäuptling un' schickt ihn zu meinem Thron. Ich werd das Angebot persönlich aussprech'n.", sourceObjective = "Holt die Zandalari in die Horde.", completion = "Ohne Euch wäre all das nicht möglich gewesen. Ihr habt gute Arbeit geleistet, mein Champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[53720] = { id = 53720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefolgschaft von Kul Tiras", description = "Es ist Zeit für ihre Jungfernfahrt, {name}.\n\nDieses so treffend benannte Schiff wird uns und seine Besatzung über das weite, offene Meer zum Hafen von Sturmwind tragen. Dort treffen wir Anduin, und ich werde den Pakt besiegeln, den wir vor so vielen Monden geschlossen haben.\n\nKul Tiras wird der Allianz beistehen, so lange ich Lordadmiralin bin.\n\nIch danke Euch für Eure Mithilfe bei diesem Unterfangen.", sourceObjective = "Segelt zum Hafen von Sturmwind und übergebt Anduin sein Geschenk.", completion = "Ich akzeptiere diese Geste in dem Geist, in dem sie gemacht wurde, {name}.\n\nDie Kul Tiraner haben sich als wertvolle Verbündete erwiesen und jetzt haben wir ein greifbares Symbol dieses Bundes.\n\nIch danke Euch für Eure fortwährende Unterstützung. Mit Eurer Hilfe wird die Allianz auch in Zukunft wachsen und stärker werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[53721] = { id = 53721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tradition der Zandalari", description = "Ihr habt während Eurer Zeit in der Horde so manche Prüfungen besteh'n müss'n. Der Stolz der Zandalari lastete auf Euern Schultern und doch habt Ihr triumphiert!\n\nKehrt zu mir zurück. Ich möchte anerkenn', was für 'n Vorbild Ihr für uns alle seid.", sourceObjective = "Trefft Königin Talanji am Goldenen Thron in Zuldazar.", completion = "Tragt diese Rüstung voller Stolz, {name}. Ihr gehört nun zu den größt'n Champions der Zandalari.", sourceObjectiveStatus = "unverified-source-field" }
quests[53722] = { id = 53722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tradition von Kul Tiras", description = "Mir ist hier in Boralus so einiges über Eure außerdordentlich vorbildliche Führung zu Ohren gekommen, {name}.\n\nWir treffen uns vor der Burg. Im Namen von Kul Tiras möchte ich Euch für Eure Anstrengungen die Ehre erweisen.", sourceObjective = "Trefft Katherine Prachtmeer in Boralus.", completion = "Wo auch immer Euch die Winde hintragen mögen, wisset, dass der Geist von Kul Tiras Euch stets begleitet.\n\nTragt unsere Farben mit Stolz, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53724] = { id = 53724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenjägerin Mutumba" }
quests[53725] = { id = 53725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein zerschmettertes Volk", description = "Obwohl das Monument die gefallenen Mitglieder der Zerschmetterten Sonne ehren sollte, erlangte es für die Sin'dorei schnell eine weitere Bedeutung.\n\nNicht weit von hier verloren wir einen unserer größten Helden, Anasterian Sonnenwanderer, den letzten König von Quel'Thalas. Er führte unseren letzten Ansturm gegen die Geißel an und kreuzte mit Arthas höchstpersönlich die Klingen. Wenn wir der Opfer gedenken, die zur Rückeroberung dieses Landes nötig waren, so gedenken wir auch der Opfer, die zu seiner Verteidigung gebracht wurden.", sourceObjective = "Entzündet die letzte Flamme.", progress = "Ja?", completion = "Vergesst niemals, wie viele hier ihr Leben verloren haben, sowohl durch die Geißel als auch durch ihre fehlgeleiteten Brüder und Schwestern.", sourceObjectiveStatus = "unverified-source-field" }
quests[53726] = { id = 53726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mechmachenschaften" }
quests[53727] = { id = 53727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legion 110 H" }
