quests[53733] = { id = 53733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legion 110 A" }
quests[53734] = { id = 53734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter Geistern wandeln", description = "Jedes Jahr bitten wir einen Champion unseres Volkes, einen Akt des Gedenkens zu Ehren jener abzuhalten, die der Geißel zum Opfer fielen. Lady Liadrin hat dieses Ritual bereits genauso wie ich und andere durchgeführt. Dieses Jahr habe ich die Ehre, Euch diese Aufgabe zu übertragen.\n\n<Der Lordregent überreicht Euch eine verzierte Laterne.>\n\nDiese Laterne trägt eine im Sonnenbrunnen geborene Flamme. Ich bitte Euch, diese Laterne zu verschiedenen, für den Untergang des Sonnenbrunnens und Quel'Thalas bedeutsamen Orten zu bringen und die Erinnerungen zu beleuchten, die wir nicht vergessen können.", sourceObjective = "Trefft Lor'themar in Tristessa.", completion = "Dieses Land wird sich nie von dem Schaden erholen, der hier angerichtet wurde. Aber wir haben an jenem Tag sehr viel mehr als nur Land verloren.", sourceObjectiveStatus = "unverified-source-field" }
quests[53735] = { id = 53735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die ersten Gefallenen", description = "Arthas bahnte eine Schneise durch das Land, um zum Sonnenbrunnen zu gelangen. Die Todesschneise dient als fortwährende Erinnerung an diese Entweihung. An ihrem Eingang hat unsere erste Verteidigungslinie versucht, die Geißel in Schach zu halten. Dort wurde das erste Blut vergossen.\n\nEs war ein Massaker.\n\nBringt die Laterne zum Grund der Todesschneise und deckt mithilfe ihres Lichts die Erinnerungen an die dortigen Ereignisse auf.", sourceObjective = "Werdet Zeuge des Untergangs der ersten Verteidiger.", completion = "<Lor'themar steht für einen Moment still da.>\n\nElor bindel felallan morin'aminor.", sourceObjectiveStatus = "unverified-source-field" }
quests[53736] = { id = 53736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wehklagen der Hochgeborenen", description = "Die nächste Erinnerung...\n\nVerzeiht mir. Für viele unserer Leute war dies der Zeitpunkt, an dem wir begriffen, dass wir des Todes waren.\n\nEs gibt eine Gedenkstätte für eine ganz besondere Verteidigerin im Westen, in ihrem Heimatort. Das Licht dort hat zweifellos einige der im Gebiet verweilenden Seelen angezogen. Werdet sie los und entzündet danach wieder die Flamme.", sourceObjective = "Entzündet die zweite Gedenkflamme.", completion = "Sylvanas und die Weltenwanderer haben mehr als die meisten von uns geopfert. Im Angesicht der derzeitigen Lage muss ich mich manchmal selbst daran erinnern.", sourceObjectiveStatus = "unverified-source-field" }
quests[53737] = { id = 53737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tag, als die Hoffnung starb", description = "Die Waldläufergeneralin fiel direkt östlich von Morgenluft, wo sie die Stellung hielt, um die Zivilisten während ihres Rückzugs nach Silbermond zu schützen. Wäre sie nicht gewesen, würde unser Volk noch viel weniger Angehörige zählen, als es ohnehin schon der Fall ist.\n\nBeleuchtet mit der Laterne das Schlachtfeld und erlebt mit, wie ihre Streitkräfte am Ende unter Arthas' persönlichem Angriff in die Knie gingen.", sourceObjective = "Werdet Zeuge des Untergangs der Waldläufergeneralin.", completion = "In den Worten einer etwas poetischeren Erzählung:\n\nAls ihre Verteidiger fielen, schrie sie leidgeplagt auf: \"Shindu fallah na, Sin'dorei.\"\n\nSie war bis zu ihrem letzten Atemzug eine wahre Waldläufergeneralin. Möge Silbermond nie ihre Tapferkeit vergessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53738] = { id = 53738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung von Quel'Danas", description = "Nachdem unsere besten Verteidiger besiegt und die Linien durchbrochen waren, machte Arthas kurzen Prozess mit den verbliebenen Streitkräften Silbermonds und stürmte durch die Stadt.\n\nHier trennen sich unsere Wege. Ich muss nach Silbermond zurückkehren, bevor Halduron seine Waldläufer entsendet, um nach mir zu suchen.\n\nDer Drachenfalkenmeister in Morgenluft hat Befehl, Euch einen Flug nach Quel'Danas zu ermöglichen. Dort trefft Ihr jemanden, der sich viel besser mit den Ereignissen auf der Insel auskennt.", sourceObjective = "Trefft Euch mit Lady Liadrin in Quel'Danas.", completion = "Seid Ihr bereit, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[53752] = { id = 53752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bomb-astisch" }
quests[53753] = { id = 53753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bomb-astisch" }
quests[53755] = { id = 53755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Fass aufmachen" }
quests[53759] = { id = 53759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebt acht da unten!" }
quests[53760] = { id = 53760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbeabsichtigte Konsequenzen", description = "<Xal'atath spricht erneut.>\n\nDie Diener von N'Zoth bereiten sich auf die Rückkehr des Meisters vor. Sie beabsichtigen, einen verheerenden Sturm heraufzubeschwören, um alle Ungläubigen auszulöschen.\n\nFür dieses besondere Ritual benötigen sie drei uralte Artefakte. Eines der Leere, eines des Sturms und eines des Meeres.\n\nIch kann selbst jetzt hören, wie das Relikt der Leere nach mir ruft. Es wird mit Energie verstärkt... oder verderbt. So genau kann ich es nicht sagen. Ich sehe es auf einer Klippe mit Blick über ein riesiges Meer.\n\nKommt, {class}, für einen solchen Schatz können wir eine viel bessere Verwendung finden.", sourceObjective = "Findet den Leerenstein in Drustvar.", progress = "Ja... diese Gestalt sollte ihren Zweck erfüllen.", completion = "Lasst Euch nicht ablenken. Es gibt noch viel für uns zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[53761] = { id = 53761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schatz der Piratin", description = "Ich spüre ein weiteres Relikt. Einen Dreizack, von dem man dachte, er sei in den Tiefen verloren gegangen. Er ruft mich, {name}. Hört Ihr ihn ebenfalls?\n\nSein Lied nimmt Gestalt an. Ich sehe einen Hafen im Osten. Eine ehrgeizige Piratin, gierig und stolz. Sie ist sich der Macht, die in ihrem Goldschatz verborgen liegt, überhaupt nicht bewusst.\n\nDer Größenwahn der Möchtegern-Kapitänin wird sie sicher anhalten, die Beute nicht einfach so herauszugeben. Ich fürchte, man muss ihr eine ziemlich harte Lektion erteilen.\n\nAber das ist doch Eure Spezialität, nicht wahr?", sourceObjective = "Findet das zweite Relikt.", progress = "Befindet sich der Dreizack in Eurem Besitz?", completion = "Ich habe keine Sekunde an Euch gezweifelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[53762] = { id = 53762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Orkanruferkrone", description = "<Xal'atath atmet tief ein und lächelt.>\n\nMeine Kraft wächst. Ich kann es jetzt deutlich sehen... das dritte Relikt, das wir suchen. Die Krone, die Orkanrufer genannt wird.\n\nWie passend, dass ausgerechnet der unersättliche Toatana derjenige sein würde, der das Artefakt nach dem Untergang Atal'Grals findet. Er krabbelte schon immer ständig in den Tiefen umher und suchte nach Schätzen für seine Sammlung.\n\nToatanas Gier hat dafür gesorgt, dass er in einer Höhle festsitzt, die er nie mehr verlassen kann. Dort wartet die Krone auf uns.", sourceObjective = "Beschafft das dritte Relikt.", progress = "Die Krone ist in unseren Händen viel nützlicher als in den Klauen eines übergroßen Siltfressers.", completion = "Ein weiterer Beweis dafür, dass Ihr und ich gemeinsam Großes erreichen können, {name}.\n\nSo viele Möglichkeiten...", sourceObjectiveStatus = "unverified-source-field" }
quests[53763] = { id = 53763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Messer drehen", description = "Die Relikte gehören uns... so wie es sein sollte.\n\nEs fehlt nur noch ein Schritt, um die großen Wahrheiten zu offenbaren.\n\nDie Naga wollten ihren Sturm von einem Ort aus heraufbeschwören, an dem uralte Macht noch nachklingt. Dieser Ort hat im Laufe der Zeiten unzählige Namen erhalten, aber Ihr Sterblichen kennt ihn zumeist als Klippe des Vergessens.\n\nIch werde vorausgehen und mit den Vorbereitungen beginnen. Trefft mich dann dort.", sourceObjective = "Trefft Euch mit Xal'atath an der Klippe des Vergessens.", completion = "<Talanji lauscht Euren Erzählungen über Xal'atath und N'Zoth.>\n\nZandalar hat sich immer noch nich' ganz vom Befall Uldirs durch den Alten Gott erholt. Wenn sich 'n weiterer erhebt...\n\nDas sind sehr bedrohliche Nachrichten. Diese Flut könn'n wir nur gemeinsam abwend'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[53765] = { id = 53765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sein Blick ruht auf Euch", description = "Etwas Dunkles hat sich in Euch eingenistet, {name}. Die Fangarme von N'Zoth bohren sich durch Euren Geist und Eure Seele und wollen alles, das Euch ausmacht, verschlingen.\n\nIch kann ein Säuberungsritual durchführen, doch nur an einem Ort, der von derselben Macht erfüllt ist, die Euch im Griff hält. \n\nTrefft mich in der Nähe des Tiegels der Stürme. Das Ritual ist gefährlich und schmerzhaft, aber es ist Eure einzige Chance, wieder frei zu sein.\n\nDer Alte Gott hat seine Augen überall. Ich möchte nicht, dass Ihr eins davon werdet.", sourceObjective = "Trefft Euch mit Bruder Pike in der Nähe des Tiegels der Stürme zur Läuterung Eurer \"Gabe\".", completion = "Es ist vollbracht. Die Dunkelheit verblasst und Euer Geist gehört wieder Euch.\n\nIhr seid von N'Zoths Einfluss befreit. Hoffen wir, dass er nicht noch einmal versucht, von Euch Besitz zu ergreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53766] = { id = 53766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sein Blick ruht auf Euch", description = "<Talanji scheint Euch besorgt zu mustern.>\n\nFinstres Mojo hat Euch befall'n, {name}. Ich spür, wie N'Zoths Tentakel sich tief in Euren Geist grab'n.\n\nDieses Übel muss ausgelöscht werd'n... bevor es Eure Seele an sich reißt!\n\nBegebt Euch zum Altar von Akunda auf der Terrasse der Auserwählten. Sucht dort Nailok auf, einen der Priester von Akunda. Er ist Eure beste Chance, von diesem mächtig'n Fluch befreit zu werd'n, der Euch in den Klauen hält.", sourceObjective = "Sucht Nailok beim Altar von Akunda auf der Terrasse der Auserwählten auf.", completion = "Das war'n bööööööses Mojo, das Euren Geist da im Griff hatte. Aber Akundas Macht hat sich als noch stärker erwies'n!", sourceObjectiveStatus = "unverified-source-field" }
quests[53768] = { id = 53768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufruhr pur" }
quests[53769] = { id = 53769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufruhr pur" }
quests[53771] = { id = 53771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gurin Steinbinder" }
quests[53772] = { id = 53772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zagg Blindauge" }
quests[53773] = { id = 53773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagaangriff!" }
quests[53774] = { id = 53774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weisheit des Kriegshäuptlings", description = "Champion. Nach unserem Kampf mit G'huun erschien uns kurz der Geist unseres alten Kriegshäuptlings Vol'jin. Er war für alle in Zuldazar klar zu sehen.\n\nHunderte Fragen an meinen alten Freund lagen mir auf der Zunge, doch sein Geist verschwand, bevor ich zu sprechen wagte.\n\nIch bat Talanji, erneut ihre Séance durchzuführen, damit ich mit Vol'jins Geist sprechen könne.\n\nWürdet Ihr Vol'jins Gleve von seiner Ruhestätte am Fuße der Pyramide beschaffen und in Zanchul zu uns stoßen?", sourceObjective = "Trefft Euch mit Prinzessin Talanji in der Halle der Hohepriester in Zanchul.", progress = "Habt Ihr die Gleve gebracht?", completion = "In diesen schwer'n Zeit'n war Baine 'n ausgezeichneter Berater. Es is' mir 'ne Ehre, ihn auf seiner Suche nach Antwort'n zu unterstütz'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[53775] = { id = 53775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Störende Schemen", description = "Vol'jins Geist is' ganz schön schwer zu fass'n. Ich hab Meister Gadrin und Geistwandler Ebenhorn gebeten, uns bei seiner Anrufung beizusteh'n.\n\nDieses Ritual wird nich' leicht werd'n. Daher bitte ich Euch, Vorkehrungen zu treff'n, falls uns etwas andres als Vol'jin besuch'n sollte.", sourceObjective = "Unterstützt das Ritual zur Beschwörung von Vol'jins Geist.", completion = "Ihr wisst, dass Ihr die richtige Frage stellt, wenn jemand Euch dafür 'n Ende setz'n will.", sourceObjectiveStatus = "unverified-source-field" }
quests[53776] = { id = 53776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Verheerten Küste", description = "An der Verheerten Küste lauerte mein Ende in der Schlacht. Die Dämonen strömt'n von allen Seiten herein. Sylvanas tat, was sie konnte, doch Thrall war besiegt und auch ich lag am Bod'n. Es war der reinste Schrecken.\n\nUnd jetzt müsst Ihr mich dorthin zurückbring'n. Bringt meine Gleve zum Schlachtfeld und ruft mich, dann werd' ich kommen. Vielleicht können wir am Ort, wo mein Blut vergoss'n wurde, etwas Licht ins Dunkel bring'n.", sourceObjective = "Bringt Vol'jins Gleve zu Geistwandler Ebenhorn an der Verheerten Küste.", completion = "Für Eure Verhältnisse mag ich uralt sein, doch mir mangelt es an der reinen Macht, die Talanji kontrolliert. Ihr solltet vielleicht einen Schritt zurückgehen. Das ist mein erster Versuch, einen so mächtigen Geist zu beschwören.", sourceObjectiveStatus = "unverified-source-field" }
quests[53777] = { id = 53777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo der Tod ihn erwartete", sourceObjective = "Beschreitet die Schatten gemeinsam mit Vol'jin.", progress = "So leicht kann man mich nich' in die Flucht schlag'n. Was sollen sie schon tun, mich noch mal töt'n?", completion = "Das gibt mir einiges, worüber ich nachdenk'n muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[53778] = { id = 53778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo er fiel", description = "Hier isses, Mann. Hier hat die Legion unsre Truppen in 'ne Falle gelockt un' mich mit 'nem Schwert durchbohrt.\n\nSylvanas zog mich ausm Verderb'n des Schlachtfelds. An dem Tag rettete sie die Horde. Kommt un' lasst uns diesen Ort zu Fuß erkund'n un' seh'n, was wir aus den Echos von der Vergangenheit lern' könn'.", sourceObjective = "Durchsucht die Kreischenden Klippen mit dem Geist von Vol'jin.", completion = "An diesem Tag hat sicher etwas unsrem Feind geholf'n. Doch wer oder was könnt' das gewes'n sein?\n\nDie Loa war'n stumm un' ihre Mächte fern, als ob ich ihre Gunst verlor'n hätt'.\n\nBei so viel Tod kann ich mir nur einen vorstell'n, der dahintersteck'n könnt'.", sourceObjectiveStatus = "unverified-source-field" }
quests[53779] = { id = 53779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lügen eines Loas", description = "Verborg'ne Erinnerung'n, Geister, die sich unsern Nachforschungen in den Weg stell'n, un' 'ne lange Spur von Leichen, seit ich Sylvanas zum Kriegshäuptling ernannt hab.\n\nIch glaub, es wird Zeit, dass Ihr mit dem alt'n Bwonsamdi sprecht. Klingt komisch, aber das is' wirklich nich' sein Stil. Was nich' heiß'n soll, dass er nich' dahintersteckt.\n\nAm best'n, Ihr arbeitet mit Talanji zusamm'. Ich hab den Eindruck, dass der Todesloa 'ne Schwäche für Ihre Hoheit hat. Ihr könnt Bwonsamdi in seiner Nekropole in Nazmir find'n. Aber... seid respektvoll.", sourceObjective = "Trefft Euch mit Talanji an der Nekropole in Nazmir.", completion = "Wir müss'n sehr vorsichtig sein. Bwonsamdi mag etwas für Humor übrig ham, aber wer ihm keinen Respekt zollt, bekommt seinen Zorn zu spür'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[53780] = { id = 53780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kerkermeister der Verdammten", description = "Ich hab viele Rivalen, wenn's ums Beanspruch'n von Seel'n geht. Doch um Vol'jin das anzutun, was Ihr da beschreibt... das stinkt nach alter Magie.\n\nEiskrone. Das is mehr als 'n hübscher Thron. Es is 'n Anker, der diese Welt auf eine Art mit der nächsten verbindet.\n\nIch werd 'n Schwarzes Tor für Euch öffnen. Schreitet hindurch un' fragt den Lichkönig, ob er sich ins Gebiet vom alten Bwonsamdi wagt.", sourceObjective = "Stellt den Lichkönig.", completion = "Ha ha. Ihr solltet aufpass'n, wenn Ihr mit den Mächten des Todes zu tun habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[53781] = { id = 53781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyir", description = "Nich' viele ham den Mumm oder das Mojo, mir etwas wegzuschnapp'n. Der alte Bwonsamdi kriegt immer seinen Anteil.\n\nAber Talanjis Schilderung nach zu schließ'n, kriegt Vol'jins Geist womöglich Hilfe von 'ner andren Macht. Un' es gibt nur wenige, die so gern mit Seelen rumspiel'n wie Eyir. Sie liebt es einfach, sich einzumisch'n... mit ihren Flügeln un' ihrem Heldenmut.\n\nIhr solltet besser persönlich mit ihr sprech'n. Sie befindet sich in ihrer Kammer in Skold-Ashil. Und erwähnt lieber nich' meinen Namen, sonst schickt sie Euch schneller zurück, als 'n Schwarzes Tor es je könnte.", sourceObjective = "Trefft Talanji in Skold-Ashil in Sturmheim.", completion = "Das is' 'n merkwürdiges Land. Die Geister fühl'n sich hier so anders an.", sourceObjectiveStatus = "unverified-source-field" }
quests[53782] = { id = 53782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse des Todes", description = "Hmph. Tja, der Lichkönig un' diese herrschsüchtige Val'kyr sin' nich' meine einzigen Rivalen. Aber sie steck'n am ehesten dahinter. Irgendjemand hantiert mit uraltem Mojo herum.\n\nSagt Vol'jins Geist, dass die Antworten, die er sucht, nich' in der Welt der Lebenden zu find'n sin'. Er muss auf die andre Seite, wenn er erfahr'n will, was er wiss'n möchte.\n\nEs gibt dort 'n paar Orte, die nur er betret'n kann.", sourceObjective = "Sprecht mit dem Geist von Vol'jin.", completion = "Also auf zur Andren Seite. Wo ich hingeh', können Lebendige nich' folg'n. Wenn es in meiner Macht steht, sag ich Bescheid, was ich gefund'n hab.\n\nPasst gut auf Euch auf. Wenn ich Baine richtig verstand'n hab, wird die Horde 'nen Helden wie Euch bald sehr nötig ham.", sourceObjectiveStatus = "unverified-source-field" }
quests[53783] = { id = 53783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Dünen", description = "Der Bauplan, den Ihr gefunden habt, ist verschlüsselt. Mit meinen Werkzeugen kann ich da nichts anfangen. Ich will nicht riskieren, die Daten zu beschädigen.\n\nAber ich kenne jemanden, der diese Nuss knacken kann: Datenguru Gryzix.\n\nWenn ich es richtig im Kopf habe, nimmt er sich in Vol'dun eine Auszeit am Strand, seit der Krieg ausgebrochen ist. Irgendetwas von wegen, niemand würde seine Arbeit würdigen.\n\nIhr könnt ihn aber bestimmt überzeugen, uns zu helfen.", sourceObjective = "Findet Datenguru Gryzix in den Vergessenen Marschen in Vol'dun.\n\nBereitgestellter Gegenstand:", completion = "Ugh, was wollt Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[53784] = { id = 53784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belagerungsingenieur Krachbumm" }
quests[53787] = { id = 53787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Modularbau", description = "Auf dem Verlassenen Schrottplatz tummeln sich einige ziemlich gefährliche gnomische Konstrukte. Die Mechakerne, die sie enthalten, sind bei der Fertigung des Üb3r-Schraubers nützlich. Wenn man den Legenden glaubt, lassen sich damit Kreationen erschaffen, die es so noch nie gegeben hat!\n\nIhr seht abenteuerlustig aus, {name}. Was meint Ihr, habt Ihr Lust, ein paar Mechs zu verschrotten?\n\nVergesst nicht Euren Bogenlichtschraubenschlüssel!", sourceObjective = "Tötet mechanische Konstrukte beim Verlassenen Schrottplatz und repariert 8 Mechakerne mit einem Bogenlichtschraubenschlüssel.", sourceObjectiveStatus = "unverified-source-field" }
quests[53791] = { id = 53791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stolz der Sin'dorei", description = "{name}, Lor'themar Theron bittet um Eure Anwesenheit in Silbermond.\n\nEr erbittet Eure Unterstützung bei einer äußerst wichtigen Zeremonie.", sourceObjective = "Sprecht mit Lor'themar in Silbermond.", completion = "Ah, {name}. Ihr kommt gerade zur rechten Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[53800] = { id = 53800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht um die Dunkelküste" }
quests[53801] = { id = 53801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht um die Dunkelküste" }
quests[53802] = { id = 53802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überzeugungsarbeit bei den Sethrak", description = "Zeigt mir mal den Bauplan...\n\nJa, ja, in Ordnung. Ich kann Euch helfen.\n\nIch brauche ein paar Dinge, um meinen Dekodierer mit Energie zu versorgen.\n\nIch muss irgendwie Elektrizität aus der Umgebungsluft kanalisieren. Da gibt es doch keine bessere Möglichkeit, als ein paar Blitzableiter von den Sethrak zu stehlen... ähm, ich meine auszuleihen, schließlich versuchen die seit Wochen, meine Technologie zu stehlen!\n\nIch bin sicher, Ihr werdet eine gewisse \"Überzeugungsarbeit\" leisten müssen, aber Ihr seid <ein ziemlich überzeugender/eine ziemlich überzeugende:r> {race}.", sourceObjective = "Sammelt Blitzableiter der Treulosen im Schuppenzahnaußenposten.", progress = "Ich brauche diese Blitzableiter für meine Arbeit, {name}.", completion = "Perfekt, das sollte reichen, um meinen Dekodierer mit Energie zu versorgen.\n\nJetzt befeuern wir alles mit Blitzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[53804] = { id = 53804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dinomant Zakuru" }
quests[53805] = { id = 53805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchs Nadelöhr", description = "Ihr könnt mich sehen?\n\nNa, da bin ich aber froh! Ich dachte, ich hätte mich in den Windungen der Zeit verirrt... mal wieder!\n\nAber um durch die Windungen des Zeitgefüges hindurchsehen zu können... müsst Ihr wahrhaftig ein äußerst begabter Schneider sein.\n\nWürdet Ihr mir dann vielleicht etwas Stoff bringen, <Schneider/Schneiderin>? Ich glaube, dann kann ich mit Eurer Hilfe herausfinden, wann genau ich mich gerade befinde, und das korrigieren.", sourceObjective = "Sammelt 5 Stücke gischtvernebeltes Leinen und 5 Stücke Tiefseesatin.", progress = "Wann in Azeroth bin ich...?", completion = "Ihr seid zurück! Das ging schnell... oder irre ich mich?", sourceObjectiveStatus = "unverified-source-field" }
quests[53806] = { id = 53806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwer wiegt das Haupt", description = "Okay, eine Sache benötige ich noch von Euch.\n\nDer Anführer der Sethrak, Kriegsfürst Elektrios, ist mir wirklich auf die Nerven gegangen.\n\nEr hat meinen Gedankenverstärker gestohlen. Ohne ihn kann ich meiner Arbeit nicht nachgehen. Er sorgt dafür, dass ich klarer denken kann und weniger... tödliche Fehler mache.", sourceObjective = "Erbeutet den goblinischen \"Gedankenverstärker\" von Kriegsfürst Elektrios im Schuppenzahnaußenposten.", progress = "Habt Ihr meinen Gedankenverstärker?", completion = "Haha! Nehmt das, Elektrios! \n\nSeht, wie toll dieses Ding ist! Jetzt wisst Ihr, warum es so wertvoll ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[53807] = { id = 53807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Stich zur rechten Zeit", description = "Hm... Ich kann mich nicht erinnern, jemals zuvor in dieser Zeit gewesen zu sein.\n\nIch sollte Euch das wohl erklären. Mein Name ist Delormi und ich bin das letzte lebende Mitglied der Synchronschneider.\n\nWir stellen sicher, dass das Gewebe der Zeit – nun ja – intakt bleibt, aber ich habe gesehen, dass sich einige Risse aufgetan haben.\n\nTatsächlich glaube ich, das ist der Grund, warum ich in dieser Zeit angekommen bin. Vielleicht könntet Ihr mich dabei unterstützen, sie zu finden und zu schließen?", sourceObjective = "Unterstützt Delormi dabei, die Zeitrisse zu schließen.", completion = "Und das sollte es gewesen sein. Obwohl... Irgendetwas stimmt noch immer nicht...", sourceObjectiveStatus = "unverified-source-field" }
quests[53808] = { id = 53808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriechend zum Sieg" }
quests[53810] = { id = 53810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der durchtrennte Faden", description = "Seht Ihr das? Da liegt eine Leiche.\n\nDer Gedanke, dass die Höhlen derart schrecklich überrannt wurden...\n\nWir sollten uns die Leichen ansehen. Vielleicht finden wir etwas Nützliches.", sourceObjective = "Untersucht die Leichen in den Höhlen der Zeit.", completion = "Das ist ein böses Omen, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[53811] = { id = 53811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kinderwoche", description = "Danke, dass Ihr gekommen seid, um die Kinderwoche zu feiern, {class}. Ihr werdet einen kleinen Jungen sehr glücklich machen!\n\nNehmt diese Pfeife. Damit könnt Ihr das Kind rufen, um welches Ihr Euch diese Woche kümmern wollt. Wie es üblich ist, hat sie nach der Kinderwoche keinen Nutzen mehr.\n\nWenn Ihr bereit seid, dann nutzt die Pfeife und trefft Euren neuen Schützling. Er kann es kaum erwarten, Euch kennenzulernen.", sourceObjective = "Benutzt die Pfeife des Kul Tiranischen Waisenkindes, um Euren Schützling zu rufen, um den Ihr Euch während der Kinderwoche kümmern werdet.\n\nBereitgestellter Gegenstand:", completion = "Hui, seid Ihr ein {class}? Das ist ja fantastisch! Ich heiße Liam!\n\nIch kann es kaum erwarten, die Stadt zu verlassen. Seit ich ganz klein war, war ich nicht mehr vor den Toren.\n\nFrau Westerson sagt immer, wir sollen darüber nachdenken, was wir werden wollen, wenn wir groß sind. Aber wie soll ich mich entscheiden, wo es so viele tolle Sachen gibt?!\n\nKönnt Ihr mich zu den Leuten bringen, von denen ich in all den Geschichten gehört habe? Ich glaube, es wird mir bei meiner Entscheidung helfen, wenn ich Erwachsene wie Euch treffe!", sourceObjectiveStatus = "unverified-source-field" }
quests[53812] = { id = 53812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine sorgfältig vorbereitete Falle" }
quests[53813] = { id = 53813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärmel hochkrempeln", description = "Die Höhlen der Zeit? Merkwürdig... hier habe ich viele Zeitlinien verbracht.\n\nWas ist an diesem Ort... dieser Zeit so besonders?\n\nDas müssen wir später genauer erörtern. Es sieht so aus, als wären wir nicht die Einzigen, die von diesen Rissen betroffen sind...\n\nLasst uns dem bronzenen Drachenschwarm einen Gefallen tun und diese Anomalien beseitigen.", sourceObjective = "Tötet 12 Chronoanomalien.", completion = "Anscheinend ist es egal, in welcher Zeit man sich befindet, es gibt immer etwas zu bekämpfen...", sourceObjectiveStatus = "unverified-source-field" }
quests[53814] = { id = 53814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rottenmeisterin Stahlzahn" }
quests[53815] = { id = 53815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist eigentlich mit Saffy Chaise?", description = "Als das Azerit entdeckt wurde, hat man meine Freundin Saffy geschickt, um herauszufinden, was es kann. Es gab einen Angriff und wir alle dachten, sie sei tot. Dann hat sich herausgestellt, dass sie zur Arbeit in einer Ideenschmiede der Goblins in Tanaris gezwungen wurde. Bevor wir sie aber da rausholen konnten, ist das ganze Ding hochgegangen.\n\nMeine Bosse haben sie jetzt als tot abgeschrieben, aber sie hat das erste Mal ja auch überlebt, also bin ich nicht so sicher. Mir wurde befohlen, nicht nach ihr zu suchen, aber Ihr könntet Euch mal umsehen.\n\nFindet Saffy – oder was von ihr übrig ist.", sourceObjective = "Sucht nach Hinweisen auf Sapphronetta Chaise in Tanaris.", completion = "<Ihr findet die verkohlten Teile einer Art mechanischer Vorrichtung. Ein Papagei vielleicht? Es ist nicht Saffy Chaise, aber ein Beweis ihrer Arbeit. Vielleicht gibt es noch mehr Hinweise in der Gegend.>", sourceObjectiveStatus = "unverified-source-field" }
quests[53816] = { id = 53816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederzusammenbau benötigt", description = "<Das Wort \"Feders\" wurde in die kaputte mechanische Kreatur geritzt. Also genau die Art von Sache, die von Eurer gesuchten Person stammen könnte.\n\nSammelt die Teile und baut das mechanische Konstrukt wieder zusammen. Vielleicht findet Ihr so Hinweise auf ihr Schicksal.\n\nIn dem Gebiet wimmelt es nur so von Plünderern und Schlägern der Venture Co. Sie haben die Taschen wahrscheinlich voll mit mechanischen Teilchen, die dazu verwendet werden könnten, Feders zu reparieren.>", sourceObjective = "Sammelt die mechanischen Teile von Angestellten der Venture Co.", progress = "<Es scheint, als hättet Ihr alle Teile gesammelt.>", completion = "<Die Teile lassen sich mit etwas gezielt eingesetzter Kraft und scharfer verbaler Motivation zusammensetzen. Hoffentlich waren die Teile, die Ihr noch übrig habt, nicht weiter wichtig.\n\nDer mechanische Papagei schwebt jetzt etwas unbeholfen über dem Sand.>", sourceObjectiveStatus = "unverified-source-field" }
quests[53817] = { id = 53817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was geschah wirklich mit Grizzek Zischzang?", description = "Als dieses ganze Azeritchaos angefangen hat, hat ein Goblin namens Grizzek Zischzang für mich geforscht. Er war schlecht fürs Geschäft und musste von der Bildfläche verschwinden. Ich dachte, die Sache wäre vom Tisch, aber jetzt ist mir zu Ohren gekommen, dass er vielleicht gar nicht tot ist.\n\nIhr müsst diesen Kerl für mich finden und in Erfahrung bringen, was passiert ist. Wenn er lebt, schaltet ihn aus und ich lege bei Eurer Belohnung den gängigen Söldnerzuschlag obendrauf.", sourceObjective = "Sucht nach Hinweisen auf Grizzek Zischzang in Tanaris.", completion = "<Ihr findet die verkohlten Teile einer Art mechanischer Vorrichtung. Ein Papagei vielleicht? Es ist nicht Grizzek Zischzang, aber ein Beweis seiner Arbeit. Vielleicht gibt es noch mehr Hinweise in der Gegend.>", sourceObjectiveStatus = "unverified-source-field" }
quests[53818] = { id = 53818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Federpflege", description = "<Trotz seiner schweren Schäden und obwohl er voller Insekten ist, könnt Ihr erkennen, dass Feders eine Art Rückrufprogramm hat. \n\nWenn Ihr den mechanischen Vogel repariert und ihm zurück zu seinem Herkunftsort folgt, findet Ihr vielleicht die Person, die Ihr sucht.\n\nIhr habt es geschafft, das Ding wieder zusammenzusetzen. Wie schwer kann es sein, die Macken eines mechanischen Papageien zu beheben?>", sourceObjective = "Behebt die Fehler in Feders' Rückrufprogramm.", completion = "<Es schien an einem Käferproblem zu liegen. Igitt. Aber die mechanische Kreatur scheint sich jetzt besser zu bewegen.>\n\nHallo! System arbeitet innerhalb normaler Parameter! Hallo!\n\n<Feders sieht Euch an und wartet auf Anweisungen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[53819] = { id = 53819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zum Nest zurück", description = "<Ihr entscheidet Euch, das Rückrufprogramm zu aktivieren. Vielleicht kann der Papagei Euch zu der Person führen, die Ihr sucht.>", sourceObjective = "Aktiviert das Rückrufprogramm.", completion = "Feders! Ihr habt ihn wieder zusammengeschraubt!\n\nDas ist zwar klasse, aber... wenn Ihr uns finden konntet, dann können das auch andere.", sourceObjectiveStatus = "unverified-source-field" }
quests[53820] = { id = 53820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie ist jetzt an einem besseren Ort", description = "Ooh, Kelsey... sie war immer eine gute Freundin. Ich wollte ihr irgendwann mitteilen, dass ich noch lebe, aber ich war abgelenkt.\n\nAzerit, der Krieg, die Nahtoderfahrung... Wir hatten viel zu tun. Für tot gehalten zu werden hat aber auch seine Vorteile. Wir haben viel geforscht und brauchen nur ein besseres Labor.\n\nIn Ordnung. Neuer Plan. Sagt Kelsey, wir melden uns. Aber nur Kelsey. Für alle anderen sind wir tot – vorerst. Wenn Ihr nichts über Grizzek verratet, könnt Ihr... Feders haben.\n\nAbgemacht?", sourceObjective = "Kehrt zu Kelsey Stahlfunken in Boralus zurück.", completion = "Sie lebt?! Das ist ja großartig! Ich kann es kaum erwarten, zu erfahren, woran sie so alles gearbeitet hat. Ich war nicht immer ein Fan von Grizzek... denn Ihr müsst wissen, dass er Saffy teilweise gehörig auf die Zahnräder gegangen ist! Aber wenn sie wieder zusammen sind, dann ist das ein schönes Paket. Hmmmmm.\n\n<Kelsey scheint für einen Moment nachdenklich, bevor sich ein diebisches Grinsen auf ihrem Gesicht breitmacht.>\n\nIch habe da eine Idee. Macht Euch keine Sorgen, {name}. Habt Spaß mit dem Papagei!", sourceObjectiveStatus = "unverified-source-field" }
quests[53821] = { id = 53821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Er ist tot, Jastor", description = "Hey, also, ich hab' hier gut was am Laufen und ich würd' es vorziehen, wenn Gallywix keinen Wind davon bekommt, dass ich noch am Leben bin.\n\nIch mache Euch deshalb einen Vorschlag. Ihr denkt Euch was Schönes aus, zum Beispiel dass Ihr kleine Stückchen von mir über ganz Tanaris verteilt gefunden habt und dass ich so richtig tot bin, und... dann könnt Ihr den Vogel behalten.\n\nAbgemacht?", sourceObjective = "Kehrt zu Gazlowe im Hafen von Zandalar zurück.", completion = "Gute Arbeit mit Gallywix, {name}. Wenn ich es nicht besser wüsste, würde ich denken, dass Grizzek tatsächlich tot ist.\n\nEr ist am Leben, richtig? Richtig.\n\nWie auch immer, hier ist Euer Bonus. Das bleibt am besten unter uns, okay?", sourceObjectiveStatus = "unverified-source-field" }
quests[53823] = { id = 53823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefolge der Königin", description = "Prinzessin Talanji hat klare Befehle gegeb'n.\n\nIhr, {name}, sollt sie an den Stufen von Zanchul treff'n. Sie möchte Euch an ihrer Seite hab'n, wenn sie sich dem Ritus der Königinnen und Könige unterzieht. Ich hoffe, Euch ist bewusst, welche Ehre das ist.\n\nDie kommende Königin wird Euch genau erklär'n, was Ihr zu tun habt.\n\nGeht jetzt, und mög'n Euch Pa'kus Winde gewog'n sein.", sourceObjective = "Trefft Euch mit Prinzessin Talanji beim Zocalo.", completion = "Da seid ihr ja. Schön, dass Ihr es geschafft habt, {name}.\n\n\n\nEs is' mir 'ne Freude, Euch zu zeig'n, wie mein Volk einen solch'n Anlass feiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[53824] = { id = 53824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritus der Königinnen und Könige", description = "Jetzt, wo Ihr hier seid, könn'n wir mit dem heiligen Ritus beginn'n.\n\nNehmt Euern Platz neben Talanji ein, {name}. Sie hat Euch für diese wichtige Aufgabe auserkor'n. Ich erklär Euch alles, während wir nach Zanchul reis'n.", sourceObjective = "Reitet in Prinzessin Talanjis Prozession.", progress = "Ihr habt Euch diese Ehre mehr als verdient, {name}.", completion = "So 'n Anlass muss mit einer groß'n Zeremonie gewürdigt werd'n, {name}. Keine Angst, Ihr werdet genug zu tun hab'n, während sich Talanji auf das Kommende vorbereitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[53825] = { id = 53825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der neue Rat der Zanchuli", description = "Das sin' ernüchternde Entwicklungen {name}.\n\nIch möchte mich mit meinen Priestern über die Vorkommnisse berat'n. Ihr sollt weiter in die Tiefen von Zanchul geh'n bis zu den Ratskammern. Dort findet Ihr den neuen Rat, den ich zusammengeruf'n hab.\n\nBegrüßt die Mitglieder und seht Euch meine Auswahl genau an. Ich hoffe, dass Ihr sie angemess'n findet.", sourceObjective = "Begrüßt den Rat der Zanchuli.", progress = "Was haltet Ihr von meiner Auswahl, {name}?", completion = "Ich bewaffne mich selbst mit dem Wissen und der Weisheit von anderen, wie es mein Vater nie getan hat. Ich hoffe, das reicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[53826] = { id = 53826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anstifter unter uns", description = "Wir könn' das Problem schnell lös'n, wenn wir denjenigen ausschalt'n, der die Gewalt zu verantwort'n hat.\n\nIch hab von einer Vollstreckerin gehört, die die Landstreicher und Arbeiter gegen die Händler und Wachen auf dem Zocalo aufstachelt.\n\nJemand von uns würde das niemals ohne Grund tun. Seht, ob Ihr den Grund für die plötzliche Veränderung ausfindig mach'n könnt.\n\nMir wurd gesagt, ihr Name sei Malzon. Ich hoffe, für sie, dass sie aufgibt.", sourceObjective = "Stellt Vollstreckerin Malzon auf dem Zocalo.", completion = "Wenn ich das richtig versteh', sind ihre Bedenken nicht ohne Grund entstand'n. Seid auf der Hut, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53827] = { id = 53827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Rat hat gesprochen", description = "Jetzt, da Ihr geseh'n habt, wen ich in meinen Rat gewählt hab, wird es Zeit, ihren Segen zu erhalt'n.\n\nEs ist eine symbolische Geste der Unterstützung, aber ich glaube, dass Worte genau so viel Macht hab'n wie Taten. Wenn sie mir die Treue schwör'n, werden die Loa auch über sie wach'n.\n\nIch hoff, meine Wahl findet ihren Gefallen, {name}. Ich bin jedenfalls überzeugt.", sourceObjective = "Erhaltet den Segen des Rats der Zanchuli.", completion = "Ich werd mich jetzt nicht auf die Worte der weißen Witwe versteif'n, aber ich werd ihre Kritik auch nich' einfach vom Tisch wisch'n. Mir wär's nur lieber gewes'n, sie hätte mit mir gesproch'n, anstatt aus den Schatten anzugreif'n.\n\nWir hätt'n zusammen die vielen Probleme der Zandalari lös'n könn'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[53828] = { id = 53828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blick der Loa", description = "Mein Rat hat seinen Segen erteilt und wir hab'n 'en Gegner erledigt. Jetzt fehlt nur noch das Urteil meiner Loa.\n\nIch weiß nich', wie dieser Teil ausgeh'n wird. Mein Vater hat niemals darüber gesproch'n, zumindest nich' mit mir.\n\nGeht mit mir. Ich erkläre Euch, was von Euch in diesem letzten Teil der Prüfung erwartet wird.", sourceObjective = "Folgt Talanji.", completion = "Ich vertrau darauf, dass Ihr Euch zurückhaltet, wo Ihr könnt, {name}. Es ist wichtig, dass ich diese Prüfungen allein bestehe.", sourceObjectiveStatus = "unverified-source-field" }
quests[53830] = { id = 53830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Königin der Zandalari", description = "Die Loa scheinen damit einverstand'n zu sein, dass ich die Krone an mich nehme. Mein Rat akzeptiert mich. Meine Priester haben mir ihren Segen gegeb'n. Mein Volk hat sein Missfallen ausgedrückt. Aber ich werd mich dieses Problems annehm'n.\n\nEs wird Zeit, die Verantwortung als Anführerin zu übernehm'n. Ich werd mich an sie wend'n und über unsre Zukunft sprech'n. Es wär mir eine Ehre, wenn Ihr an meiner Seite steh'n würdet, wenn ich das tue.", sourceObjective = "Wohnt dem Aufstieg von Talanji zur Königin der Zandalari bei.", completion = "Ich bin fest entschloss'n, unser Volk zusammenzuführ'n, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53831] = { id = 53831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein königlicher Anlass", description = "Möchtet Ihr wissen, wie die Zandalari der Horde beigetreten sind? Mein Volk und die Zandalari hatten eine... komplizierte Vergangenheit.\n\nAllerdings glaube ich, dass wir es damals mit den Zandalari der Vergangenheit zu tun hatten. Die jetzige Königin Talanji unterscheidet sich sehr von ihrem Vater.\n\nVerzeihung, ich plappere. Unsere Geschichte beginnt, nachdem die Allianz die Stadt Zuldazar angegriffen und König Rastakhan getötet hatte.\n\nDie Horde wurde von der damaligen Prinzessin Talanji eingeladen, ihrer Krönungszeremonie in Zuldazar beizuwohnen...", sourceObjective = "Trefft den Abgesandten der Zandalari am Großen Siegel in Dazar'alor.", completion = "Da seid Ihr ja. Die Zeremonie hat fast schon angefang'n. Die Prinzessin hat nach Eurer Anwesenheit an den Stufen von Zanchul verlangt.", sourceObjectiveStatus = "unverified-source-field" }
quests[53832] = { id = 53832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegensabotage" }
quests[53833] = { id = 53833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rachsüchtige Reise", description = "<Ihr hebt die Notiz auf und erkennt, dass die Venture Co. hinter dem Mord an Datenguru Gryzix steckt. Ihr durchsucht seine Leiche: Sein Dekodierer und der Bauplan für den Üb3r-Schrauber wurden gestohlen.\n\nIhr müsst seinen Dekodierer und den Bauplan finden und beides zurück zu Shuga Sprengkapp bringen, wenn Ihr den Üb3r-Schrauber bauen möchtet.\n\nDer Mech, der Euch folgt, könnte sich dabei als nützlich erweisen.>", sourceObjective = "Findet das Lager der Venture Co. und holt Gryzix' Dekodierer und den verschlüsselten Bauplan für Üb3r-Schrauber.", progress = "Alles klar, {name}? Hat Gryzix den Bauplan für Euch fertig gemacht?", completion = "Er ist tot? Armer Kerl, er war ein herausragender Ingenieur.\n\nIch danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53835] = { id = 53835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vielleicht etwas Wertvolles?", description = "<Die Tafel ist so abgegriffen, dass sie nicht mehr lesbar ist. Auch wenn einige Zeichen zu entziffern sind, könnt Ihr die Tafel unmöglich ohne Hilfe lesen.\n\nIhr könnt nur ein Wort erkennen: Aegrim.>", sourceObjective = "Bringt die Tafel zu Brann Bronzebart in der Halle der Forscher in Eisenschmiede.", completion = "Ich liebe ordentliche Artefakte!", sourceObjectiveStatus = "unverified-source-field" }
quests[53836] = { id = 53836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Rüstung, uraltes Geheimnis", description = "Bei meinem Barte! Wisst Ihr, was das ist?! Auf dieser uralten Tafel ist beschrieben, wie man das Bollwerk des Bergkönigs schmiedet!\n\nDer letzte Träger dieser Rüstung war Aegrim Bronzebart, einer meiner Vorfahren und Than des Bronzebartklans.\n\nSprecht mit Berater Belgrum. Er wird mehr über Aegrims Vergangenheit wissen und kann vielleicht ein wenig mehr über die Legenden dieser Rüstung aufdecken.", sourceObjective = "Sprecht mit Berater Belgrum in der Altstadt von Eisenschmiede.", completion = "Es war die richtige Entscheidung, zu mir zu kommen. Ich glaube, ich kann Euch helfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[53837] = { id = 53837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer gut aufpassen", description = "Habt Ihr Aegrim gesagt? Bollwerk des Bergkönigs? Nun, dann sollten wir die Suche in Aegrims Arbeitszimmer beginnen. Der Eingang befindet sich unter uns in den Tiefen der Altstadt von Eisenschmiede.\n\nDas einzige Problem ist, dass sich uns ein paar Troggs in den Weg stellen werden. Geht Ihr doch voran.", sourceObjective = "Tötet 8 angreifende Troggs und Steinbeiß den Wühler in der Altstadt von Eisenschmiede.", completion = "Die Wachen kümmern sich um das Versiegeln der Tunnel. Wir haben eine wichtige Aufgabe vor uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[53838] = { id = 53838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bleibt auf dem Boden", description = "{name}! Die Forscherliga bereitet eine neue Ausstellung in der Halle der Forscher vor.\n\nEin Zwergentrupp ist losgezogen, um nach neuen Artefakten zu suchen, die wir dort ausstellen können.\n\nSie sind zum Steinbruch Gol'Bolar in Dun Morogh aufgebrochen und bisher nicht zurückgekehrt. Würdet Ihr bitte mal nach ihnen sehen?", sourceObjective = "Durchsucht den Steinbruch Gol'Bolar nach der vermissten Ausgrabungsmannschaft.", completion = "<Das Team scheint die Zwergentafel beschützt zu haben.>", sourceObjectiveStatus = "unverified-source-field" }
quests[53839] = { id = 53839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aegrims Arbeitszimmer", description = "Dort entlang geht es zu Aegrims Arbeitszimmer. Ich muss noch einige Schriftrollen sortieren, also könnt Ihr das Arbeitszimmer nach Belieben durchstöbern.\n\nIch bin sicher, Brann wäre an Euren Funden sehr interessiert.", sourceObjective = "Durchsucht Aegrims Arbeitszimmer nach dem Bollwerk des Bergkönigs.", completion = "<Der Rüstungsständer ist leer.>", sourceObjectiveStatus = "unverified-source-field" }
quests[53840] = { id = 53840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kann ich Euch für ein Gebräu begeistern?", description = "Die Rüstung mag zerbrochen sein, doch noch bleibt Hoffnung. Mit den gesammelten Bruchstücken können wir sie möglicherweise neu schmieden.\n\nDas ist nicht gerade mein Gebiet, doch es gibt jemanden, der uns vielleicht helfen könnte. Wir sollten mit Grumnus Scharfstahl sprechen. Er hat sich nach Thelsamar in Loch Modan zurückgezogen.\n\nGeht schon voraus, ich werde Euch dort treffen.", sourceObjective = "Findet Grumnus Scharfstahl in Loch Modan.", completion = "Brann hat mir schon berichtet, was geschehen ist. Diese Tafel wird uns sicher anleiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[53841] = { id = 53841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragmente der Vergangenheit", description = "<Die Rüstung, die einst hier war, wurde auf mysteriöse Weise zerschmettert. Die Stücke der uralten Rüstung sind im Raum verteilt.>", sourceObjective = "Sammelt die zerschmetterten Stücke der Rüstung ein.", progress = "Was habt Ihr denn da?", completion = "Die Rüstung ist zerschmettert? Hmm...", sourceObjectiveStatus = "unverified-source-field" }
quests[53842] = { id = 53842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Segen der Erde", description = "Ignis wird Euch beim Schmelzen des Metalls helfen, doch die Hitze der Schmiede würde Euch in Euren Stiefeln braten!\n\nUnsere Vorfahren, die Zwerge, die Aegrims Rüstung einst schmiedeten, konnten ihre Steingestalt sehr viel länger aufrechterhalten als wir heutzutage. Nur so konnten sie das Bollwerk überhaupt schmieden.\n\nGlücklicherweise kann uns dabei unser Freund Bergfels aushelfen. Er braucht nur ein paar Materialien für das Ritual.", sourceObjective = "Findet den Überrest des Rituals der Irdenen in der Altstadt von Eisenschmiede.", progress = "Habt Ihr ihn?", completion = "Das wird genügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53843] = { id = 53843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ub3rlode" }
quests[53844] = { id = 53844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekrutierung des Meisters des Eisenwerks", description = "Grumnus sagt, zum Schmelzen dieses Metalls werden wir ein wenig Hilfe benötigen. Und ich weiß auch schon, wer für diese Aufgabe perfekt geeignet ist.\n\nWir gehen nach Ulduar!\n\nVor vielen Jahren kämpften wir dort gegen ein Konstrukt namens Ignis, Meister des Eisenwerks. Man erzählt sich, dass die Titanenhüter ihn zurückgebracht haben und dass Ulduars Ofen erneut brennt.", sourceObjective = "Rekrutiert Ignis, Meister des Eisenwerks, als Hilfe beim Schmelzen des Metalls.", progress = "Lange her, seit ich das letzte Mal in Ulduar war.", completion = "Mit Ignis' Hilfe sind wir einen Schritt näher daran, die Rüstung neu zu schmieden!", sourceObjectiveStatus = "unverified-source-field" }
quests[53845] = { id = 53845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmieden der Rüstung", description = "Zeit, zu beginnen. Bergfels, Ignis und ich sind hier, um Euch zu unterstützen.\n\nIhr werdet der erste Zwerg in vielen Generationen sein, der das Bollwerk des Bergkönigs schmiedet. Es ist mir eine Ehre, dem beizuwohnen.\n\nSeid Ihr bereit?", sourceObjective = "Schmiedet das Bollwerk des Bergkönigs.", progress = "Ist es erledigt?", completion = "Ich hätte nie gedacht, dass ich diesen Tag noch erlebe.", sourceObjectiveStatus = "unverified-source-field" }
quests[53846] = { id = 53846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erbe der Bronzebarts", description = "Ihr müsst diese Rüstung sofort Muradin zeigen! Dies ist ein historisches Ereignis für das Zwergenvolk.\n\nEs ist nicht nur eine Rüstung, es ist ein Symbol unserer Traditionen.", sourceObjective = "Bringt das Bollwerk des Bergkönigs zu Muradin Bronzebart am Hohen Sitz.", completion = "{name}, schon lange wart Ihr ein Champion für das Zwergenvolk. Eure Taten deuten von Ehre und Tapferkeit und die Lieder über Euch werden in diesen Hallen noch lange erklingen.\n\nIch kann mir keinen {race} vorstellen, der es mehr verdient hätte, diese Rüstung zu tragen, als Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[53847] = { id = 53847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wispern im Wind", description = "{name},\n\nich brauche Eure Dienste.\n\nMaiev und Shandris sind auf dem Weg nach Sturmwind, um König Wrynn zu ersuchen, bei der Rückeroberung der Dunkelküste zu helfen.\n\nIhr habt Euch in der Vergangenheit als loyal gegenüber meinem Volk erwiesen, und deswegen bitte ich Euch, an der Audienz beim König teilzunehmen und unsere Sache zu unterstützen.\n\nIch glaube, dass wir uns bald wiedersehen werden.\n\n-Tyrande", sourceObjective = "Trefft Euch mit Maiev Schattensang und Shandris Mondfeder in Burg Sturmwind.", completion = "Ich habe mir schon gedacht, dass Tyrande Euch benachrichtigt, sobald sie von unserem Vorhaben erfährt.", sourceObjectiveStatus = "unverified-source-field" }
quests[53848] = { id = 53848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werkzeug in Vol'dun", description = "Okay, {name}. Wir haben fast alles, was wir brauchen. Fast.\n\nIch habe nämlich meinen Werkzeugkasten verloren. Ich muss ihn fallen gelassen haben, als ich vor ein paar Tagen vor den Sethrak geflohen bin. Könnt Ihr ihn mir wiederbringen? Ohne meine Werkzeuge bin ich nur ein halber Ingenieur!\n\nUnd nehmt einen Mech mit. Ich habe ein paar merkwürdige Zwergen- und Trollgestalten da draußen gesehen... hoffentlich nicht von der Venture Co. Wenn die auch nur ahnen, dass der Bauplan hier ist, sind wir in großen Schwierigkeiten.\n\nIhr werdet den Gedankenverstärker brauchen, damit er Euch folgt. Setzt ihn einfach auf und los geht's!", sourceObjective = "Legt den goblinischen Gedankenverstärker an und findet den Werkzeugkasten von Datenguru Gryzix.", progress = "<Gryzix scheint tot zu sein.>", completion = "<Ihr stellt den Werkzeugkasten neben seinen Leichnam auf den Boden.>", sourceObjectiveStatus = "unverified-source-field" }
quests[53849] = { id = 53849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwindende Hoffnung", description = "Die Kaldorei waren seit Ende des Dritten Krieges immer standhafte Verbündete der Allianz. Wir haben in fernen Landen und sogar anderen Welten gekämpft, ohne jeden Vorbehalt.\n\nEs ist schon sehr sonderbar, dass sie ausgerechnet jetzt, wenn wir Hilfe brauchen, so wenige Ressourcen haben, dass sie uns nicht einmal eine einzige Klinge leihen können.\n\nWrynn hat Tyrande bereits die Hilfe verweigert. Überzeugt Euch selbst.", sourceObjective = "Seht Euch Tyrandes Audienz bei Anduin Wrynn an.", progress = "Das geht so nicht.", completion = "Egal, was der Menschenkönig sagt, Tyrande wird sich nicht von ihrem Vorhaben abbringen lassen. Aber noch hat er die Chance, zu handeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[53850] = { id = 53850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unser Krieg geht weiter", description = "Die Allianz ist noch lange nicht gestoppt. Es liegt noch eine Menge Arbeit vor uns, {name}. Aber dank Euch haben wir die notwendigen Mittel, um die Allianz zu brechen.\n\nDas Abyssische Szepter wurde König Rastakhan überbracht, was uns in seiner Gunst hat steigen lassen.\n\nIch möchte mit Euch über eine äußerst wichtige Angelegenheit sprechen... aber nicht hier.\n\nTrefft mich an Bord der Klagelied in Zuldazar.", sourceObjective = "Sprecht mit Sylvanas Windläufer an Bord der Klagelied in Zuldazar.", completion = "Derek Prachtmeers Leiche wird uns gute Dienste leisten. In der Zwischenzeit haben wir noch Arbeit zu erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53851] = { id = 53851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unser Krieg geht weiter", description = "Die Allianz ist noch lange nicht gestoppt. Es liegt noch eine Menge Arbeit vor uns, {name}. \n\nKönig Rastakhan ist jetzt im Besitz des Abyssischen Szepters, das Ihr den Kul Tiranern abgenommen habt. Er hat es... in seiner Schatzkammer verstaut. \n\nDie Dunkle Fürstin wünscht, Euch bezüglich des Leichnams zu sprechen, den Ihr am Meeresgrund gefunden habt. Es ist Derek Prachtmeer.", sourceObjective = "Sprecht mit Sylvanas Windläufer an Bord der Klagelied.", completion = "Unsere Pläne, die Allianz und ihre Verbündeten zu Fall zu bringen, wurden in Gang gesetzt.\n\nWir haben viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[53852] = { id = 53852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Azerit für Euch", description = "Die Kul Tiraner und die Allianz häufen große Mengen Azerit und Azeritwaffen im Tiragardesund an.\n\nSie haben sich dank ihres Siegs über Lady Aschenwind und ihre Leute eine neue Quelle für diesen Rohstoff erschlossen.\n\nWir müssen gegen ihre Azeritvorräte einen Schlag führen und die Waffen zerstören, sonst geraten wir bei diesem Krieg ins Hintertreffen.\n\nIhr und Zelling werdet zum Tiragardesund reisen und dort Rexxar treffen. Führt den Angriff auf ihre Azeritvorräte an.\n\nUnd kehrt erst dann zurück, wenn Ihr siegreich wart.", sourceObjective = "Trefft Rexxar im Tiragardesund.", completion = "<Rexxar nickt.>\n\nIhr seid hier. Unsere stärksten Krieger warten ungeduldig darauf, das Anwesen anzugreifen.\n\nErfüllen wir ihnen diesen Wunsch.", sourceObjectiveStatus = "unverified-source-field" }
quests[53853] = { id = 53853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die untergehende Sonne", description = "Für den Sonnenbrunnen.\n\nEs gibt einen Grund, weshalb wir mit diesen Worten in die Schlacht reiten. Wir haben an jenem Tag so viel verloren...\n\nIch habe an jenem Tag so viel verloren.\n\nBringt die Laterne auf die Südseite der Insel, wo die Todesschneise auf das Meer trifft, und lasst sie dort leuchten. Dann werdet Ihr den Anfang vom Untergang des Sonnenbrunnens sehen. Und den letzten Akt der Hochelfen.", sourceObjective = "Wohnt dem Fall von Anasterian bei.", progress = "Ist es vollbracht, Champion?", completion = "Es bleibt noch eine Aufgabe.", sourceObjectiveStatus = "unverified-source-field" }
quests[53856] = { id = 53856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn der Horde", description = "Auf dem Anwesen der Norwinsens lagern eine Menge Azerit und die neuesten Azeritwaffen der Allianz.\n\nWir müssen die Waffen und das gesamte Azerit stehlen. Jede gestohlene Waffe bedeutet ein gerettetes Leben der Horde.\n\nSobald Ihr bereit seid, zuzuschlagen, gebt mir Bescheid. Ich werde unseren Kriegern das Zeichen zum Angriff geben.\n\nDie Allianz und die Kul Tiraner werden die wahre Macht der Horde zu spüren bekommen!", sourceObjective = "Befehlt der Armee der Horde, das Anwesen der Norwinsens anzugreifen.", completion = "Unsere Streifkräfte haben die Kul Tiraner zurückgeschlagen. Die Jagd beginnt!", sourceObjectiveStatus = "unverified-source-field" }
quests[53857] = { id = 53857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Käpt'n Gorok" }
quests[53858] = { id = 53858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In ihren Fußstapfen", description = "Noch so ein Riss. Normalerweise würde ich ihn reparieren, aber unter diesen Umständen will ich wissen, wo er hinführt.\n\nIch verkehre nicht oft mit alternativen Versionen meiner selbst aus anderen Zeitsträngen. Aber eine bestimmte Version von mir ist seit Längerem eine gute Freundin.\n\nIch merke, wie ich schwächer werde. Wenn sie vergeht...\n\nWir haben nicht viel Zeit. Wir müssen sofort in diesen Riss gehen.", sourceObjective = "Betretet den Zeitriss mit Zeitweberin Delormi.", progress = "Wir müssen uns beeilen. Sonst befürchte ich das Schlimmste.", completion = "Was... Was passiert hier?!", sourceObjectiveStatus = "unverified-source-field" }
quests[53859] = { id = 53859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Bergvolk", description = "Die Leute aus Kul Tiras sind wirklich hart im Nehmen, aber die Raubeine sind die Härtesten von allen!\n\nSie können Greifen mit ihren bloßen Händen niederringen! Sie schlagen einen Yeti mit einem einzigen Schlag bewusstlos!\n\nIch will ein Raubein treffen und beweisen, dass ich genauso stark sein kann wie sie! Könnt Ihr mich zu ihrem Lager bringen? Ich habe gehört, es ist oben in den Bergen bei der Angelpunktwerft.", sourceObjective = "Nehmt Liam mit und besucht die Raubeine im Lager der Raubeine im Tiragardesund. Ruft ihn zu Euch, falls er nicht anwesend sein sollte, wenn Ihr ankommt.", completion = "Habt Ihr das gehört?! Er hat gesagt, ich könnte ein Raubein sein!\n\nIch werde ab jetzt ganz viel essen, damit ich so groß und so stark werde wie er!", sourceObjectiveStatus = "unverified-source-field" }
quests[53861] = { id = 53861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yo Ho, Yo Ho!", description = "Die Waisenmatrone sagt uns immer, was wir tun sollen! Studiert eure Bücher, übt eure Wörter, benehmt euch...\n\nAber was ist, wenn ich Pirat werden will, wenn ich groß bin? Ein Schrecken der Weltmeere? Den ganzen Tag Schätze finden und Duelle ganz oben im Krähennest austragen. Und bei all dem hätte ich einen abgefahrenen Hut auf!\n\nIn Boralus sieht man nie echte Piraten, deswegen kenne ich sie nur aus Geschichten. Ich will einen echten Piraten treffen! Bringt Ihr mich nach Freihafen? Auf dem Weg werde ich meine Piratenstimme üben.\n\nHARRRRR!", sourceObjective = "Nehmt Liam mit und besucht einen Piraten in der Nähe von Freihafen im Tiragardesund. Ruft ihn zu Euch, falls er nicht anwesend sein sollte, wenn Ihr ankommt.", completion = "Seht Euch nur meinen neuen Hut an! Was für ein netter Pirat!", sourceObjectiveStatus = "unverified-source-field" }
quests[53862] = { id = 53862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tintenfischschrein", description = "Manchmal kommen Gezeitenweise zum Waisenhaus und erzählen uns vom Meer und wie sie mit ihm reden.\n\nIch will auch mit dem Wasser reden!\n\nWir haben sie schon in ihrem Kloster hier in Boralus besucht, aber ich habe gehört, dass ihre Heimat in Sturmsang noch viel beeindruckender sein soll. Könnt Ihr mich dort hinbringen? Ich muss es sehen! Ich habe gehört, die Aussicht von den Salzwerken aus soll fantastisch sein!", sourceObjective = "Nehmt Liam mit und besucht den Strand in der Nähe der Seemannsrinne im Sturmsangtal, um den Schrein des Sturms zu sehen. Ruft ihn zu Euch, falls er nicht anwesend sein sollte, wenn Ihr ankommt.", completion = "Dieser Gezeitenweise war so geheimnisvoll! Kennt Ihr ihn?\n\nIch will auch so mysteriös sein wie er! Er kann sogar fliegende Wasserstrudel beschwören! Und er hat erzählt, dass das Wasser mit ihm spricht! Ist das nicht abgefahren?!\n\nJetzt bin ich pitschnass.", sourceObjectiveStatus = "unverified-source-field" }
quests[53863] = { id = 53863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vogelfreunde", description = "Mein bester Freund im Waisenhaus heißt Billy. Aber er ist nur ein ganz normales Kind wie ich. Ich habe aber gehört, dass es Leute in Drustvar gibt, die FALKEN als beste Freunde haben.\n\nDas ist so toll!\n\nKönnen wir einen Falkner besuchen? Bitte, bitte? Ich will auch einen Vogelfreund haben.\n\nIch habe gehört, bei Aroms Wehr gibt es eine große Statue von irgendeinem toten Typen, der mit den Vögeln befreundet war. Vielleicht finden wir dort einen Falkner!", sourceObjective = "Nehmt Liam mit und besucht die Statue von Arom Kronsteig bei Aroms Wehr in Drustvar. Ruft ihn zu Euch, falls er nicht anwesend sein sollte, wenn Ihr ankommt.", completion = "Hmm...\n\nIch glaube, der erste Schritt, sich mit einem Vogel anzufreunden, ist es, aufzuhören, Möwen zu jagen, und sie stattdessen zu füttern!", sourceObjectiveStatus = "unverified-source-field" }
quests[53864] = { id = 53864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestaltwandler!", description = "Es ist ja schön und gut, ein Mensch zu sein, aber wie wäre es, ein BÄR zu sein?\n\nDruiden können Bären sein. Und Katzen. Und noch ganz viele andere Tiere!\n\nIch habe Gerüchte über Druiden in den Bergen von Drustvar gehört. Es wäre so aufregend, einen zu treffen. Ich will sehen, wie sie sich in Tiere verwandeln! Vielleicht können sie mir das auch beibringen!", sourceObjective = "Nehmt Liam mit und besucht einen Druiden in Ulfars Höhle in Drustvar. Ruft ihn zu Euch, falls er nicht anwesend sein sollte, wenn Ihr ankommt.", completion = "Könnt Ihr mich irgendwann wieder mit hierhernehmen? Dieses Spiel macht bestimmt Spaß!", sourceObjectiveStatus = "unverified-source-field" }
quests[53865] = { id = 53865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Waisenhaus", description = "Das war die beste Kinderwoche aller Zeiten!\n\nVorher hatte ich Angst davor, groß zu werden, aber jetzt kann ich es kaum erwarten! Ich kann alles sein, was ich will!\n\nAber wie treffe ich die richtige Wahl?\n\nIch glaube, es ist jetzt Zeit, wieder zum Waisenhaus zurückzukehren, {name}. Auf dem Weg nach Hause denke ich darüber nach, was ich mal sein will, wenn ich groß bin.", sourceObjective = "Bringt Liam zurück zum Waisenhaus in Boralus. Ruft ihn zu Euch, falls er nicht anwesend sein sollte, wenn Ihr ankommt.", completion = "Ich hatte so viel Spaß mit Euch, {name}! Vielen Dank für diese Reise durch ganz Kul Tiras!", sourceObjectiveStatus = "unverified-source-field" }
quests[53866] = { id = 53866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wem der Schuh passt...", description = "Dieses Ding bringt sie um... bringt MICH um!\n\nWir müssen das beenden!\n\nBitte, ich brauche Eure Hilfe, um mich zu retten!", sourceObjective = "Haltet Delormis Schemen auf, bevor er Großmagistrix Delormi tötet.", completion = "Das kann nicht sein... Warum passiert das alles?", sourceObjectiveStatus = "unverified-source-field" }
quests[53867] = { id = 53867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ingenieur Bolzenhalt" }
quests[53868] = { id = 53868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet Neun", description = "Ich habe sie dort drinnen gesehen. Sie hat einen weiteren Abschnitt meiner Zeitlinie zerstört.\n\nMit jedem Faden, den sie durchtrennt, verliere ich mich mehr und mehr...\n\nVielleicht werde ich vergehen, aber ich werde nicht zulassen, dass sie das Gewebe der Zeit zerstört.\n\nIhr müsst mir noch ein letztes Mal helfen. \n\nIch kann das nur mit Eurer Hilfe beenden.", sourceObjective = "Betretet den Zeitriss.", completion = "Das ist das Ende, Schneider. Ich werde nicht länger leiden.", sourceObjectiveStatus = "unverified-source-field" }
quests[53869] = { id = 53869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit totschlagen", description = "{name}, bleibt jetzt an meiner Seite.\n\nIch bin schwach. Es wurden schon so viele Fäden durchtrennt.\n\nIch nutze meine restliche Macht, um den Riss zu schließen. \n\nBitte... Ihr müsst dafür sorgen, dass das Gewebe der Zeit vor ihr sicher ist.", sourceObjective = "Tötet Delormis unendlichen Schemen.", completion = "So, es ist also vollbracht. Der letzte Faden ist durchtrennt.", sourceObjectiveStatus = "unverified-source-field" }
quests[53870] = { id = 53870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gäste in der Feste Grommash", sourceObjective = "Trefft Eure Gäste in der Feste Grommash.", completion = "Ich bin froh, dass Ihr gekommen seid, {name}.\n\nIhr sollt das, was wir zu sagen haben, vor allen anderen hören.", sourceObjectiveStatus = "unverified-source-field" }
quests[53874] = { id = 53874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihre Wacht beenden" }
quests[53875] = { id = 53875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebelfockfreibeuter für einen Tag" }
quests[53877] = { id = 53877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Begegnung im Osten" }
quests[53878] = { id = 53878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notfallbefreiung" }
quests[53879] = { id = 53879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Räumung des Anwesens", description = "Wir müssen weiter vorrücken. Unser Ziel ist es, die Allianz zu schwächen, ihre Waffen zu zerstören und ihr Azerit zu stehlen.\n\nWir drei werden eine Schneise der Zerstörung durch unsere Feinde schlagen. Auf geht's!", sourceObjective = "Schwächt die Verteidiger auf dem Anwesen der Norwinsens.", progress = "Gebt der Allianz nicht nach!", completion = "Die Allianz und die Kul Tiraner sind unseren Streitkräften nicht gewachsen!", sourceObjectiveStatus = "unverified-source-field" }
quests[53880] = { id = 53880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsgerät und Azerit", description = "Das Anwesen der Norwinsens... Ich erinnere mich daran, wie ich mit meiner Frau und den Kindern hier spazieren gegangen bin.\n\nTut mir leid, jetzt ist nicht der richtige Zeitpunkt, in Erinnerungen an ein früheres Leben zu schwelgen.\n\nDie Allianz hat überall auf dem Anwesen Azeritbomben und -waffen verteilt. Wir müssen sie uns holen.\n\nWenn die Allianz doch nur nicht das Anwesen als Testgelände gewählt hätte... Dies sollte ein Ort des Friedens sein.", sourceObjective = "Besorgt 4 Azeritbomben und 3 Azeritgewehre.", progress = "Ist es erledigt?", completion = "Ich wünschte, die Kul Tiraner hätten nicht versucht, das Anwesen der Norwinsens mit in diesen Wahnsinn hineinzuziehen... doch hier sind wir nun.", sourceObjectiveStatus = "unverified-source-field" }
quests[53881] = { id = 53881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus demselben Stoff", description = "Mein unendliches Ich hatte recht. Ich kann die Zeit nicht länger weben.\n\nEs wurden zu viele meiner Fäden durchtrennt. Ich kann keine anderen Fäden fühlen.\n\nIch bin jetzt alleine und habe keine Fäden mehr. Ihr seid es aber nicht.\n\nNehmt dieses Muster. Ihr habt Euch als <talentierter Schneider/talentierte Schneiderin> Eurer eigenen Zeit erwiesen und als <Retter/Retterin> für so viele andere.\n\nDas Gewebe der Zeit braucht Eure Hände, um weiter gewebt zu werden. Ich vertraue Euch diese verantwortungsvolle Aufgabe an.\n\nSprecht mit mir, wenn Ihr bereit seid. Ich bringe Euch in die Zeit zurück, in der all das angefangen hat.Ihr erlernt:", sourceObjective = "Bittet Zeitweberin Delormi, Euch in Eure Zeit zurückzubringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53882] = { id = 53882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es begann an der Mauer", description = "Lange Zeit hat die südliche Mauer Quel'Thalas von dem einst großen Königreich Lordaeron getrennt. Wir hätten nicht gedacht, dass jemand sie durchbrechen könnte. Diese Vermessenheit war unser Untergang. \n\nAls die Geißel eintraf, wurde das Tor nicht mit Gewalt überwunden, sondern ein Verräter öffnete es freiwillig.\n\nObwohl wir unvorbereitet getroffen wurden, eilten alle Weltenwanderer, Soldaten und Magister aus der Gegend zur Verteidigung ihres Heimatlands. Nur sehr wenige von ihnen kehrten nach Hause zurück. Die Tore dienen jetzt als Mahnmal in ihrem Namen.", sourceObjective = "Entzündet die Flamme des ersten Denkmals.", progress = "Nehmt Euch so viel Zeit, wie Ihr benötigt.", completion = "Und jetzt folgt ihrem Weg.", sourceObjectiveStatus = "unverified-source-field" }
quests[53883] = { id = 53883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestade von Zuldazar", description = "Streitkräfte der Allianz greifen Zuldazar an. Mögen sie jeden Schritt bereuen, den sie auf unserem Land unternommen haben.", sourceObjective = "Schlagt die Streitkräfte der Allianz zurück, die Zuldazar angreifen.", completion = "Zuldazar anzugreifen war selbst für die Allianz ungewöhnlich überheblich.\n\nDanke, dass Ihr ihnen höchstpersönlich gezeigt habt, welch schlechte Entscheidung das war. Unsere Verbündeten, die Zandalari, werden beruhigt sein, dass wir zu ihnen halten, und durch unsere Machtdemonstration zu ihrer Verteidigung ermutigt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[53885] = { id = 53885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vereinzelter Sieg", description = "Streitkräfte der Allianz rücken in Vol'dun immer weiter vor. Wir können diese Aggression nicht weiter dulden!", sourceObjective = "Schlagt die Streitkräfte der Allianz zurück, die Vol'dun angreifen.", completion = "Im Namen aller Bewohner von Vol'dun danke ich Euch für Eure Hilfe, die Eindringlinge der Allianz zurückzudrängen.\n\nDie Leute hier haben sich auch ohne die Allianz schon unter genug Bedrohungen gelitten.\n\nWir werden weder die Opfer vergessen, die die Horde hier gebracht hat, noch Eure.", sourceObjectiveStatus = "unverified-source-field" }
quests[53886] = { id = 53886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besichtigung auf eigene Faust" }
quests[53887] = { id = 53887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Krieg marschiert weiter", description = "Ich hoffe, die Horde wird es sich in Zukunft zweimal überlegen, bevor sie Kul Tiras angreift. Doch nach dem Handeln ihrer Anführer zu urteilen, ist das bestenfalls eine dürftige Hoffnung. Dennoch, das Wichtigste ist, dass mein Volk jetzt sicher ist.\n\nDie Flotte und die Seeleute dürften bald hier eintreffen, um den Sturmtaklern bei der Beseitigung der letzten verbliebenen Hordenstreitkräfte zur Hand zu gehen. Bitte kehrt zu Hochkommandant Wyrmbann zurück und lasst ihn wissen, dass ich mich den anderen sobald wie möglich wieder anschließen werde.\n\nIch danke Euch für Euer schnelles Eingreifen heute, {name}.", sourceObjective = "Kehrt zu Halford Wyrmbann an Bord der Erlösenden Winde zurück.", completion = "Das war in der Tat eine erfolgreiche Operation. Ich bin froh, Lady Jaina wieder unter den Mitgliedern der Allianz zu wissen. Wir haben gemeinsam unser Bestes gegeben, doch die zusätzliche Macht der Flotte aus Kul Tiras und ihrer neuen Lordadmiralin könnte genau das sein, was wir brauchen, um diese Kampagne voranzutreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[53888] = { id = 53888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Angelpunktwerft", description = "Ein Angriff auf die Angelpunktwerft kann nur eins bedeuten: Die Horde will das Meerestor dort zerstören. \n\nDies ist mein Zuhause. Dies ist mein Volk. Ich kann meine Aufmerksamkeit erst unseren Operationen in Zandalar widmen, wenn wir die Horde in die Knie gezwungen haben.\n\nDas Militär wird etwas Zeit zum Mobilisieren benötigen, aber in der Zwischenzeit können wir beide uns diesen Monstern stellen. Wir können sie vielleicht nicht aufhalten, aber zumindest verlangsamen.\n\nDer Krieg ist erneut an meinen Gestaden gelandet. Ich werde nicht weichen.", sourceObjective = "Begleitet Jaina Prachtmeer zur Angelpunktwerft und steht ihr dort zur Seite.", progress = "Die Horde hat dieses Gebiet überrannt. Wir dürfen nicht zulassen, dass das so weitergeht.", completion = "Wie ich vermutet habe. Sie versuchen hier einen Stützpunkt zu errichten und die Kaimauer zu zerstören.", sourceObjectiveStatus = "unverified-source-field" }
quests[53889] = { id = 53889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Absichtserklärung", description = "Unsere Karawane ist bereit, die Welt jenseits der Sande zu erkunden, aber Nishas Klinge kann nicht unsere einzige Verteidigung gegen die Gefahren sein, die uns gewiss erwarten.\n\nDeshalb sind wir hergekommen.\n\nUm unsere Absicht zu erklären, uns der Horde anzuschließen.", sourceObjective = "Bezeugt Kiros Absichtserklärung, der Horde beizutreten.", completion = "Ich bin von seiner Antwort enttäuscht, aber nicht überrascht.\n\nUnsere Stärke wird oft übersehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53890] = { id = 53890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Verbündete, neue Probleme", description = "Baine hat jedenfalls alle Hände voll zu tun. Neue Verbündete aufzunehmen, bringt immer auch neue Probleme mit sich.\n\nFinden wir heraus, was den Mitgliedern der Horde Sorgen bereitet und wie wir ihnen helfen können.\n\nVielleicht wird Baine unseren wahren Wert erkennen, wenn er nicht so überfordert ist.", sourceObjective = "Findet heraus, was Kommandant Dresh, Klingenwache Sonji und der Ersten Arkanistin Thalyssra Sorgen bereitet.", progress = "Finden wir heraus, was den Mitgliedern der Horde Sorgen bereitet und wie wir ihnen helfen können.", completion = "Gute Arbeit, {name}. Manchmal wollen andere einfach nur gehört werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[53891] = { id = 53891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Problem ist zu klein", description = "Diese Probleme mögen trivial erscheinen, aber sie werden im Laufe der Zeit an der Horde nagen, wenn man sich ihnen nicht widmet.\n\nWir müssen unsere Hilfe anbieten.\n\nDie Vulpera sind geschickt darin, Probleme zu lösen, egal, wie groß diese sind.\n\nIch werde mir den Außenposten ansehen. Nisha und Meerah kümmern sich um die anderen.\n\nTrefft mich im Schattenhochland, wenn Ihr bereit seid.", sourceObjective = "Trefft Kiro im Schattenhochland.", completion = "Verlassen, genau wie Kommandant Dresch sagte.", sourceObjectiveStatus = "unverified-source-field" }
quests[53892] = { id = 53892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo sind die Arbeiter?", sourceObjective = "Findet heraus, wo die Schmetterschlagpeons hingegangen sind.", progress = "Hier muss es sein.", completion = "Die Peons rebellieren? Es überrascht mich, dass es so lange gedauert hat...", sourceObjectiveStatus = "unverified-source-field" }
quests[53893] = { id = 53893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wenig guter Wille", description = "Es klingt, als ob die Peons sich nicht wertgeschätzt fühlen. Sie leisten wichtige Arbeit für die Horde, aber ihr Pflichtbewusstsein wird oft übersehen. Ein wenig guter Wille könnte viel bewirken.\n\nLasst uns ein Fest zu ihren Ehren planen. Wir brauchen ziemlich viel Fleisch, um ihren gewaltigen Appetit zu stillen. Zum Glück habe ich ein Totem, das dabei helfen kann.\n\nIhr holt die Zutaten und ich bereite ein Festmahl zu, das die Moral garantiert hebt.", sourceObjective = "Sammelt 100 Säblerflanken, 100 Stücke Worgfleisch und 100 Gluckenhäppchen.", progress = "Habt Ihr das Fleisch mitgebracht?", completion = "Wir werden heute Abend köstlich speisen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53894] = { id = 53894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lohnende Reparaturen", description = "Die Peons haben recht. Diese Werkzeuge sind unverzeihlich.\n\nWie kann man von ihnen erwarten, ihre Arbeit zu tun, wenn ihnen die richtigen Werkzeuge für ihren Beruf fehlen?\n\nIch kann die nötigen Reparaturen vornehmen, aber erst brauche ich etwas Erz.", sourceObjective = "Sammelt 15 Stücke Zwielichterz, damit Kiro die Werkzeuge der Peons reparieren kann.", progress = "Habt Ihr Erz gefunden?", completion = "Damit kann ich arbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[53895] = { id = 53895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Peonbeförderungen!", description = "Ich gebe den Peons recht. Man sollte sie für ihre Arbeit belohnen.\n\nEs ist unwahrscheinlich, dass die Horde zustimmen wird, ihren Lohn zu erhöhen, aber es gibt keinen Grund, weshalb sie nicht befördert werden sollten.\n\nJeder Titel außer Peon würde etwas Selbstvertrauen aufbauen.", sourceObjective = "Befördert einige Schmetterschlagpeons im Peonschlupfwinkel.", progress = "Wurden die Peons schon befördert?", completion = "Ich bin sicher, Euer Lob bedeutet den Peons viel.", sourceObjectiveStatus = "unverified-source-field" }
quests[53896] = { id = 53896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchhalten", description = "Die Horde wird bezahlen für das, was sie getan hat, aber zunächst muss ich mich um die Leute hier kümmern. \n\n{name}, ich muss ein Portal offen halten, damit die Verletzten nach Boralus evakuiert werden können.\n\nHaltet mir die Horde vom Leib, während sich die Verwundeten in Sicherheit bringen. Wir können uns mit den Hordetruppen auseinandersetzen, wenn die Zivilisten sicher sind.", sourceObjective = "Schützt Jaina Prachtmeer.", completion = "Wenn die Angreifer bisher nicht wussten, dass wir hier sind, dann wissen sie es jetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[53897] = { id = 53897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Party zu Euren Ehren", description = "Ich glaube, ich habe alles Nötige, um den heutigen Abend zu einem Erfolg zu machen.\n\nWir müssen nur sicherstellen, dass die Peons herkommen.\n\nSagt ihrem Anführer, dass die Horde eine Party zu ihren Ehren gibt.\n\nIch bin sicher, sie werden einen Abend mit freiem Essen und Trinken nicht abschlagen.", sourceObjective = "Informiert Vorarbeiter Magrok, dass die Horde eine Party für die Peons veranstaltet.", completion = "Ein voller Erfolg, findet Ihr nicht?", sourceObjectiveStatus = "unverified-source-field" }
quests[53898] = { id = 53898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kraft und Ehre", description = "Diese Peons sehen doch wirklich glücklich aus, nicht wahr? Ich bezweifle nicht, dass sie morgen früh wieder an die Arbeit gehen werden.\n\nSollte ihrem Anführer allerdings niemand seine Grenzen aufzeigen, wird immer das Risiko eines Aufstands bestehen.\n\nIhr müsst Euch mit ihm messen.\n\nZeigt ihm die wahre Stärke der Horde, aber auch die Ehre, die durch Gnade gezeigt wird.", sourceObjective = "Kämpft gegen Vorarbeiter Magrok und zeigt sowohl Stärke als auch Ehre.", progress = "Warum zeigt ihr Vorarbeiter Magrok nicht die wahre Stärke Eurer Horde?", completion = "Wie die Peons sagen würden: Arbeit erledigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[53899] = { id = 53899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Außenbezirken", description = "Wenn die Dinge für den Kommandanten geklärt sind, solltet Ihr bei Nisha vorbeischauen.\n\nIch bin sicher, sie kann Eure Hilfe brauchen.", sourceObjective = "Sucht Nisha an der Südküste von Zuldazar auf.", completion = "Sonji war zu Recht besorgt.\n\nDie Naga planen einen Angriff, aber ich habe einen Plan, um sie aufzuhalten.\n\nWir müssen uns allerdings beeilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53900] = { id = 53900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir benutzen ihre Waffen", description = "Wir werden Spezialwaffen brauchen, um Gezeitenruferin Nezara zur Strecke zu bringen. Wie gut, dass die Naga reichlich davon zu haben scheinen.\n\nWir setzen ihre eigenen Waffen gegen sie ein. Davon verstehen wir beide etwas.\n\nSchnappt Euch eine Auswahl. Wir werden mehr als eine brauchen.", sourceObjective = "Sammelt 10 Waffen der Nazeshi von Truppen in den Schreckensperlenuntiefen.", progress = "Habt Ihr die Waffen?", completion = "Eine große Auswahl. Perfekt.", sourceObjectiveStatus = "unverified-source-field" }
quests[53901] = { id = 53901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosionen zeigen immer die gewünschte Wirkung", description = "Der Bereich um Gezeitenruferin Nezara ist schwer bewacht, also müsst Ihr eine Ablenkung für mich schaffen.\n\nNehmt diese Sprengladungen. Bringt sie an den Harpunenschleudern der Naga an. Ihre Detonation sollte ausreichen, um die Wachen in die Flucht zu schlagen!", sourceObjective = "Bringt flüchtigen Sprengstoff an den Harpunenschleudern der Naga an und lasst sie detonieren, um eine Ablenkung zu schaffen.", completion = "Ihr seid wirklich überragend, wenn es darum geht, Dinge in die Luft zu jagen!", sourceObjectiveStatus = "unverified-source-field" }
quests[53902] = { id = 53902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gezeitenruferin ausschalten", description = "Auch ohne Schild ist Nezara nicht wehrlos.\n\nSie hat einen Schläger an ihrer Seite, der Ärger machen könnte. Ich kümmere mich um ihn, damit Ihr die Gezeitenruferin ausschalten könnt.", sourceObjective = "Tötet Gezeitenruferin Nezara.", completion = "Ihr macht gute Arbeit, {name}. Es war mir ein Vergnügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53903] = { id = 53903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treffen mit Meerah", description = "Offenbar machen wir gute Fortschritte.\n\nWürdet Ihr Euch mit Meerah treffen?\n\nIch möchte sichergehen, dass sie den Weg zu den Winzern in Suramar gefunden hat.", sourceObjective = "Sucht Meerah in den Zwielichtrebgärten Suramars auf.", completion = "Weinhändler Iltheux hat ernsthafte Personalprobleme.", sourceObjectiveStatus = "unverified-source-field" }
quests[53904] = { id = 53904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Winzerassistenten", description = "Weinhändler Iltheux beaufsichtigt die gesamte Arkweinproduktion für die Horde.\n\nEr ist es gewohnt, den Wein selbst herzustellen, aber die Horde hat Hilfe entsandt, um den Vorgang zu beschleunigen.\n\nDas hatte den gegenteiligen Effekt.\n\nWir müssen der Sache auf den Grund gehen.\n\nWie wäre es, wenn Ihr Euch in den Weinbergen anseht, wie die Dinge dort laufen? Ich habe noch ein paar Fragen an den Weinhändler.", sourceObjective = "Sprecht mit Micah Breithuf, Boss Mida und Nomi.", completion = "Das klingt für mich, als ob wir unser Problem gefunden hätten.", sourceObjectiveStatus = "unverified-source-field" }
quests[53905] = { id = 53905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihre Stärken nutzen", description = "Iltheux nutzt die Hilfe, die man ihm geschickt hat, nicht sinnvoll.\n\nÄndern wir das.\n\nGebt den Arbeitern neue Rollen, die mehr ihren Stärken entsprechen.\n\nWenn Ihr Vorschläge braucht, helfe ich Euch gerne.", sourceObjective = "Gebt Micah Breithuf, Boss Mida und Nomi neue Aufgaben.", completion = "Weinhändler Iltheux scheint zufrieden zu sein. Ihr habt wirklich ein Händchen dafür, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[53906] = { id = 53906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Horde fermentiert", description = "Weinhändler Iltheux' Rezept muss nur wenig verbessert werden.\n\nEs sind nur einige einzigartige Zutaten und leichte Modifikationen beim Weinherstellungsprozess nötig.\n\nIch glaube, fermentierte Feuerblüten sollten die gewünschte Wirkung haben. Dann filtert man alles durch ein Spezialtuch aus Seidenflügelfasern.\n\nIn den Weinbergen gibt es viele Seidenflügel und ich habe keinen Zweifel, dass Boss Mida die Blumen für einen gewissen Preis besorgen kann.", sourceObjective = "Sammelt die benötigten Zutaten, um einen Wein herzustellen, der der Horde würdig ist.", progress = "Gemeinsam werden wir einen Wein herstellen, der der Horde würdig ist.", completion = "Ausgezeichnete Arbeit, {name}. Das wird die gewünschte Wirkung haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[53907] = { id = 53907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nippen und genießen", sourceObjective = "Bringt eine Probe von Nomis Wein zu Weinhändler Iltheux und holt Euch seine Zustimmung.", progress = "Ich hoffe, er mag den Wein.", completion = "Ich glaube, unsere Arbeit hier ist getan!", sourceObjectiveStatus = "unverified-source-field" }
quests[53908] = { id = 53908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere Ankunft wird erwartet", description = "Gehen wir zurück nach Orgrimmar.\n\nIch bin sicher, Kiro erwartet uns.\n\nWir sollten ihn wirklich nicht warten lassen.", sourceObjective = "Kehrt zur Feste Grommash in Orgrimmar zurück.", completion = "{name}, ich habe den Vulpera einen schlechten Dienst erwiesen.\n\nIch fürchte, mein Versehen könnte die Horde einen beachtlichen Verbündeten gekostet haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[53909] = { id = 53909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belagerte Verbündete", description = "Kaimauern können wiederaufgebaut werden, aber Leben sind unwiderruflich verloren. Wir müssen erst für die Sicherheit der restlichen Leute hier sorgen.\n\nDie Sturmtakler sind als die unerbittlichsten Jäger dieser Gewässer bekannt. Findet ihre Anführerin, Rosalinde Mertens, und sichert Euch ihre Hilfe bei der Befreiung der Angelpunktwerft. Säubert gemeinsam die Nordküste von der Horde, rettet alle, die sich in Gefahr befinden, und ruft die Hafenarbeiter zusammen.\n\nIhr kümmert Euch um die Nordküste, {name}. Ich übernehme die Südküste. Wir treffen uns in der Mitte und zermalmen die Horde zwischen uns.", sourceObjective = "Findet Rosalinde Mertens.", completion = "Ihr und die Lordadmiralin seid ein erfreulicher Anblick, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53910] = { id = 53910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlagt die Horde zurück!", description = "Die Horde hat die Angelpunktwerft überrannt, tötet meine Leute und zerstört ihre Lebensgrundlage. Ihre Plünderer sind nach Kul Tiras gekommen und haben nur Töten im Sinn. Ich kann das nicht zulassen.\n\nTötet jeden Axtwerfer oder Berserker der Horde, den Ihr an der nördlichen Küste seht. Ich werde dasselbe im Süden tun. Gemeinsam werden wir diese Invasion aufhalten.", sourceObjective = "Besiegt Axtwerfer oder Berserker der Horde an der Nordküste der Angelpunktwerft.", completion = "Ich sehe, die Reihen der Horde haben sich ziemlich gelichtet.\n\nIch bin sicher, die Lordadmiralin wird zufrieden sein. Ich bin es jedenfalls. Nicht übel, Festländer.", sourceObjectiveStatus = "unverified-source-field" }
quests[53912] = { id = 53912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd ist nie zu Ende", description = "Wir haben unseren Sieg, aber wir müssen uns beeilen, um uns das restliche Azerit vom Anwesen zu schnappen.\n\nUnsere Streitkräfte sollten bereits dabei sein, das Azerit vom Anwesen zu unserer Gyrokopterwerkstatt zu bringen.\n\nWir sollten uns auf den Weg machen und sicherstellen, dass wir der Allianz jedes Gramm Azerit wegnehmen.", sourceObjective = "Begebt Euch zum Anwesen der Norwinsens.", completion = "Wir haben unser Azerit, aber irgendetwas stimmt nicht. Die Kanoniere hätten inzwischen hier eintreffen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53913] = { id = 53913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Ehre", description = "Die Streitkräfte der Allianz und aus Kul Tiras sind in Auflösung begriffen. Ich kann hören, wie der Azeritpanzer warmläuft.\n\nLeutnant Krause will gegen uns kämpfen... jetzt, da seine Streitkräfte vernichtet wurden.\n\nLasst mich wissen, wenn Ihr kampfbereit seid. Wir drei werden diesen Panzer vernichten, während unsere Krieger dabei zusehen!", sourceObjective = "Besiegt Leutnant Krause.", progress = "Seid Ihr bereit?", completion = "Es ist vorbei. Immerhin ist Krause ehrenhaft gestorben.", sourceObjectiveStatus = "unverified-source-field" }
quests[53914] = { id = 53914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mord in der Shlae'gararena", description = "Der Rüstmeister der Shlae'gararena liegt tot vor Euch. Er wurde am helllichten Tag ermordet!\n\nEr muss getötet worden sein, während in der Arena gekämpft wurde, vielleicht sogar während eines Eurer Kämpfe.\n\nVielleicht gibt es in der Nähe einige Hinweise auf den Täter.", sourceObjective = "Untersucht den Tatort.", completion = "Ihr hattet also vor, den Mord selbst zu untersuchen? Interessant...\n\n<Kommandant Rabenpelz kritzelt etwas nieder, sieht zu Euch auf und schreibt dann seine Notiz zu Ende.>", sourceObjectiveStatus = "unverified-source-field" }
quests[53915] = { id = 53915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoch mit den Fäusten", description = "Wisst Ihr was?\n\n<Der Kommandant legt sein Notizbuch beiseite.>\n\n<Ein guter/Eine gute:c> {class} wäre in meinem Ermittlungsteam durchaus willkommen. In letzter Zeit hatten wir Personalengpässe und ich kann ehrlich gesagt jede Hilfe gebrauchen.\n\nAber zuerst: Warum springt Ihr nicht in die Arena und kämpft ein bisschen, damit ich sehen kann, was Ihr so draufhabt?", sourceObjective = "Gewinnt 3 Kämpfe in der Shlae'gararena.", completion = "Während Ihr gekämpft habt, habe ich mich ein bisschen über Euch schlaugemacht, {name}. Sehr beeindruckend, muss ich sagen.\n\nEntschuldigt meinen anfänglichen Argwohn. Und willkommen in unserem Team.", sourceObjectiveStatus = "unverified-source-field" }
quests[53916] = { id = 53916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmtakler auftakeln", description = "Mein Volk hat sich der Horde im offenen Kampf gestellt, als sie eintraf, aber wir waren über die ganze Werft verstreut. Die Horde war gnadenlos. Wir konnten mit nur unseren Fäusten als Waffen keinen soliden Widerstand aufbauen.\n\nAber jetzt ist die Lordadmiralin mit dem Champion der Allianz hier. Das ist genau der Funke, den wir benötigen, um uns zu erheben und diese erbärmlichen Bastarde aus unserem Land zu werfen. Wenn Ihr meinen Leuten ein paar Waffen beschaffen könnt, werden sie sich dem Kampf anschließen!\n\nFindet diese Waffen, dann treffen wir uns hier wieder. Ich arbeite an einem Plan.", sourceObjective = "Beschafft 10 Sturmtaklerwaffen.", progress = "Für Kul Tiras! Für die Lordadmiralin!", completion = "Jetzt, da mein Volk sich zur Wehr setzen kann, habe ich einen Plan, um zu verhindern, dass noch mehr dieser Wilden meine schöne Werft verschandeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[53917] = { id = 53917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdeckte Ermittlerin: Sharisanda", description = "Grubenboss Buxdotzel ist in diesem Fall einer der Hauptverdächtigen. Buxdotzel ist ein berüchtigter aggressiver Spekulant, und seine Schuldenliste ist ellenlang.\n\nEr braucht sicherlich Geld, was zu den Beweisen passt, die Ihr vorhin gefunden habt.\n\nSharisanda arbeitet an dem Fall. Ich möchte, dass Ihr sie unterstützt. Ich glaube, ihr werdet gut zusammenarbeiten.", sourceObjective = "Meldet Euch bei Sharisanda in der Shlae'gararena.", completion = "{name}? Sharisanda. Freut mich, Eure Bekanntschaft zu mach'n.\n\nBuxdotzel findet Ihr dort drüben, mit dem lächerlich'n Hut aufm Kopf.\n\nNein, nein... Starrt ihn nich' so auffällig an! Wir ermitteln hier verdeckt, Holzkopf.", sourceObjectiveStatus = "unverified-source-field" }
quests[53918] = { id = 53918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Finanzpartizipationsanregung", description = "Buxdotzel scheint dort drüben 'ne Art Wettspiel zu veranstalt'n. Die Leute könn' Kämpfergold auf ihren Favoriten setz'n.\n\nFindet raus, wie das Spiel genau funktioniert. Wenn Ihr genug Geld von ihm gewinnt, redet er vielleicht...", sourceObjective = "Gewinnt 100 Kämpfergold von Grubenboss Buxdotzels Ratespiel.\n\nWenn das Spiel gerade nicht aktiv ist, könnt Ihr es einfach aktivieren, indem Ihr einen Risikospielvertrag von Tiana Nimmermorn kauft.", progress = "Wollt Ihr ein bisschen Gold verdienen?", completion = "{name} war Euer Name? Ihr seid gar nicht mal so schlecht! Wegen Euch lande ich noch unter der Brücke, wenn das so weiter geht!", sourceObjectiveStatus = "unverified-source-field" }
quests[53919] = { id = 53919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gluck, gluck, gluck", description = "Hordeangreifer segeln weiter durch das Meerestor herein, aber wir haben eine böse Überraschung für sie!\n\nDie Sturmtakler sind sehr gut darin, alle Arten von Monstern zu bekämpfen. Das schließt auch die Horde mit ein. Wir halten sie Euch vom Hals, während Ihr ihre Boote ausschaltet.\n\nSchickt sie auf den Grund des Hafens!\n\nFür Kul Tiras! Für die Lordadmiralin!", sourceObjective = "Zerstört die Motorboote der Horde.", completion = "Wir haben die Flut der Horde eindämmen können. Jetzt müssen wir uns um die Goblinpioniere kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[53920] = { id = 53920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gefallen für Euren alten Freund Buxdotzel", description = "Hey, Ihr, ich habe über etwas nachgedacht...\n\nErinnert Ihr Euch an das ganze Gold, das Ihr von mir gewonnen habt? Na ja, lustige Geschichte... Das war vielleicht ein wenig mehr, als ich wirklich habe, und jetzt wollen ein paar kräftige Kerle mir die Ellenbogen und die Knie brechen.\n\nIch kann sie nämlich nicht ausbezahlen!  Hehe!\n\nDamit ich aus dieser misslichen Lage herauskomme, müsstet Ihr einfach nur Euren nächsten Kampf verlieren. Fallt um wie ein einbeiniger Weitschreiter! Bitte.", sourceObjective = "Verliert einen Kampf in der Shlae'gararena.", progress = "Bitte, Ihr müsst mir helfen! Sie haben gesagt, sie brechen mir meinen Geldknochen! Ich weiß nicht mal, wo der ist!", completion = "Danke, {name}. Ihr seid ein echter Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[53921] = { id = 53921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schulden des Grubenbosses", description = "Ich bin nicht zu stolz, , um ein Unrecht wiedergutzumachen. Und wisst Ihr, welches Unrecht ich meine? Dass ich kein Geld mehr habe!\n\nNur eine Person hat noch mehr Gold von mir gewonnen als Ihr, und sein Name ist Lord Sylysthrel. Ein richtig schleimiger Typ. Ich glaube, er hat gemogelt.\n\nEs wäre natürlich super, dieses Gold zurückzubekommen...", sourceObjective = "Beschafft Euch einen großen Haufen seriös erworbenes Kämpfergold von Lord Sylysthrel.\n\nIhr könnt Lord Sylysthrel herausfordern, indem Ihr seine Herausforderungskarte von Kartenhändlerin Ami kauft.", progress = "Wenn ich erst einmal das Gold zurückhabe, das ich verloren habe, geht es erst RICHTIG los mit den Wetten!", completion = "<Buxdotzel starrt verklärt auf den großen Haufen Geld.>\n\nIch liebe Gold einfach. Es gibt NICHTS, was ich nicht für Gold machen würde. Hört Ihr? NICHTS.", sourceObjectiveStatus = "unverified-source-field" }
quests[53922] = { id = 53922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweispaket: Grubenboss Buxdotzel", description = "Ich habe alles gehört. Dieser Goblin äußert sich ja wirklich sehr lautstark über seine Schulden und seine Verbrechen, nicht wahr?\n\nKlingt, als hätten wir genug, um ihn zum Verhör vorzuladen. Ich habe für Kommandant Rabenpelz ein schönes Beweispaket geschnürt.\n\nIhr habt gute Arbeit geleistet.", sourceObjective = "Bringt das Beweispaket zu Kommandant Arlu Rabenpelz.", progress = "Habt Ihr etwas über Buxdotzel herausgefunden?", completion = "<Kommandant Rabenpelz begutachtet das Beweismaterial.>\n\nDas ist mehr als genug für einen Haftbefehl. Ausgezeichnete Arbeit, {name}. Aber Ihr seid hier noch nicht fertig.", sourceObjectiveStatus = "unverified-source-field" }
quests[53923] = { id = 53923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdeckte Ermittlerin: Steingardistin Mollivox", description = "Ich glaube, eine meiner anderen Ermittlerinnen kennt Ihr schon: Steingardistin Mollivox. Sie ermittelt gegen unseren zweiten Verdächtigen, Schattenmeister Skrizzik.\n\nIhr findet Mollivox in der Nähe des Eingangs zur Arena.", sourceObjective = "Sprecht mit Steingardistin Mollivox bei der Shlae'gararena.", completion = "{name}? Mollivox. Schön, Euch zu sehen. Mal wieder.\n\nSkrizzik findet Ihr dort drüben. Geht hinüber zu ihm. Ich warte hier und greife ein, wenn es brenzlig wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[53924] = { id = 53924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelenscherben", description = "<Skrizzik murmelt in sich hinein.>\n\nOh je, oh je... Es wird wieder hungrig. Wo finde ich nur genug Seelen, um es zu füttern? Ohh... Wenn ich nur an einen dieser Preisgeldbeutel herankommen würde...\n\n<Er bemerkt Euch.>\n\nOh! Hallo Ihr! Ignoriert einfach das zerstreute Gemurmel eines unschuldigen Hexenmeisters. Hier geschieht gerade überhaupt nichts Verdächtiges!", sourceObjective = "Sucht in den Preisgeldbeuteln nach etwas, was mit \"Seelen\" zu tun hat.\n\nDie Preisgeldbeutel werden den Siegern in der Shlae'gararena überreicht. Einige Beutel sind sicher lukrativer als andere.", progress = "Oh je, oh je... Es darf nicht zu hungrig werden...", completion = "Die... Die könnten mir helfen! Helfen bei diesem... Problemchen, das ich habe. Wovon ich Euch nichts erzählen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[53925] = { id = 53925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mächtige Seelenscherben", description = "<Skrizzik murmelt wieder vor sich hin.>\n\nSind diese hier auch groß genug? Es hat solch einen Hunger nach Seelen, und wenn es nicht genug bekommt, wird es sehr böse. Wir wollen sicherlich keine  mitten in Orgrimmar auslösen. Oh je, oh je...\n\n<Er bemerkt Eure Anwesenheit.>\n\nOh! <Unser/Unsere:r> {race} ist immer noch hier! Heh heh. Kümmert Euch nicht um mich! Hier geht überhaupt nichts Böses vor!", sourceObjective = "Holt 3 mächtige Seelenscherben aus Beuteln des Prüglers, die den Gewinnern von Prügeleien verliehen werden.\n\nEine Prügelei ist ein großer Gruppenkampf in der Shlae'gararena, bei dem alle Kämpfer in der Warteschlange gegen einen mächtigen Herausforderer antreten. Eine Prügelei kann jederzeit gestartet werden, indem man eine Prügeleikarte von Tiana Nimmermorn kauft.", progress = "<Skrizzik sieht sich panisch in der Arena um.>\n\nWo kann ich mehr Seelen finden? Vielleicht verkauft der Rüstmeister welche? Moment, der ist ja tot. Hmm...", completion = "Die... sind... PERFEKT!\n\nWenn Ihr mich jetzt bitte entschuldigen würdet. Ich muss ein bisschen wirklich harmlose |cFF0000FFSchattenmagie|r wirken. Auf Wiedersehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[53926] = { id = 53926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grund zur Besorgnis", description = "Schattenmeister Skrizziks Verhalten war ungewöhnlich.\n\nSein ständiges Gemurmel über \"Schattenmagie\" und \"Leerenapokalypsen\" und \"uralte Kreaturen, die nach den Seelen der Lebenden trachten\", ist allemal Grund genug für eine nähere Untersuchung.\n\nIhr solltet Euch bei Steingardistin Mollivox melden.", sourceObjective = "Erstattet Steingardistin Mollivox Bericht..", completion = "<Mollivox hört sich Euren Bericht an.>\n\nHmm. Ja. Ich glaube, ich weiß, was da vor sich geht. Es sieht so aus, als müssten wir dieses Problem mithilfe der Wissenschaft lösen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53927] = { id = 53927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das wertvolle 13-zähnige Schutzbrillengetriebe", description = "Wir müssen etwas erfinden. Irgendein Gerät, mit dem wir in alternative Dimensionen sehen können. Etwas Explosives, das direkt über den Augen getragen wird.\n\nGenau, ich spreche von einer Brille.\n\nIch habe schon alle Teile für die Brille beisammen außer einem: ein 13-zähniges Getriebe. Es ist wirklich sehr selten und schwierig zu finden, aber ich WEISS, dass die Jungs der GG Ingenieurskunst GmbH eins haben. Kartenhändlerin Ami hat ihre Herausforderungskarte.", sourceObjective = "Besorgt ein 13-zähniges Schutzbrillengetriebe von der GG Ingenieurskunst GmbH. Ihr könnt ihre Herausforderungskarte bei Kartenhändlerin Ami kaufen.", progress = "Seid Ihr bereit für Eure neue Brille?", completion = "<Mollivox hämmert das Getriebe unsanft in eine Schutzbrille.>\n\nSo! Brille fertig.", sourceObjectiveStatus = "unverified-source-field" }
quests[53928] = { id = 53928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mollivox' Schutzbrillenexperiment", description = "Okay, bevor wir anfangen, zuerst ein paar Regeln:\n\nErstens: Diese Brille funktioniert nur auf kurze Distanz. Wir suchen nach etwas IN der Arena, also müsst Ihr auch IN der Arena sein, wenn Ihr sie benutzt.\n\nZweite Regel: Wenn Ihr bemerkt, dass etwas kurz vorm Explodieren ist, blinzelt einfach ganz stark.\n\nUnd zu guter Letzt: Vergesst nicht, dass wir nach einem bösen Schattenmonster suchen. Ihr müsst es nicht töten. Ihr müsst es nur sehen, damit wir es für unsere Beweisführung verwenden können.\n\nAlso gut, dann geht jetzt in die Arena und testet die Brille!", sourceObjective = "Setzt Mollivox' Schutzbrille auf, während Ihr in der Shlae'gararena kämpft, und sucht nach Beweisen gegen Schattenmeister Skrizzik.", completion = "<Mollivox hört aufmerksam zu, als Ihr von dem Grauen berichtet, das Ihr in der Arena gesehen habt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[53929] = { id = 53929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweispaket: Schattenmeister Skrizzik", description = "Wir haben unseren Täter wohl gefunden, {name}. Dieser Mann ist zwielichtig und verzweifelt. Zudem passt seine Schattenmagie zu der dubiosen Schriftrolle, die Ihr zuvor gefunden habt.\n\nBringt Arlu dieses Beweispaket, damit wir unseren Hauptverdächtigen festnehmen können. Gute Arbeit!", sourceObjective = "Bringt das Beweispaket zu Kommandant Arlu Rabenpelz.", progress = "Gibt es Neuigkeiten über Skizzik?", completion = "<Der Kommandant sieht sich die Notizen an.>\n\nVerflucht. Es ist schlimmer, als ich dachte. Wir nehmen ihn besser schnell fest. Dieser Typ ist total durchgedreht.", sourceObjectiveStatus = "unverified-source-field" }
quests[53930] = { id = 53930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdeckter Ermittler: Nugg Lumbo", description = "Es gibt noch eine weitere Verdächtige, gegen die ich ermittle: Libbiara Seuchenflucht, ein reicher, prominenter Blutelfentodesritter. Sie verbringt den Großteil ihrer Zeit damit, das Geschehen in der Arena von einem Zeppelin aus zu beobachten.\n\nIch habe meinen besten Ermittler auf den Fall angesetzt: Nugg Lumbo. Meldet Euch bei ihm und fragt ihn, wie es mit seinem Bericht vorangeht.", sourceObjective = "Meldet Euch bei Nugg Lumbo auf dem Luftsack, dem Zeppelin über der Shlae'gararena.\n\nDer Luftsackteleporter befindet sich direkt außerhalb Shlae'gararenabar.\n\nWenn Ihr den Teleporter benutzen möchtet, müsst Ihr entweder Rang 6 in der Shlae'gararena erreichen oder jemand muss ein Mietformular für Zeppeline von Tiana Nimmermorn kaufen.", completion = "Psst! Nugg nicht auffliegen lassen.\n\nSie dort drüben. Redet mit ihr. Nugg beobachtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[53931] = { id = 53931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer hat, der hat", description = "Seufz... wie langweilig...\n\nOh, Ihr seid es! {name}, nicht wahr? Ich habe einige Eurer Kämpfe gesehen. Sie waren nicht ganz so eintönig wie die meisten stumpfsinnigen Blutsportkämpfe, die diese Arena in letzter Zeit hervorgebracht hat.\n\nWarum sorgen wir nicht für etwas Abwechslung? Wir könnten uns etwas Edles zu trinken gönnen und dem Pöbel unter uns eine Runde von dem billigen Zeug spendieren? Und dann werfen wir ein paar Bernsteinsamenbrötchen vom Zeppelin?", sourceObjective = "Trinkt eine Flasche Geldbräu, gebt am Tresen der Shlae'gararena eine Runde aus und trefft einen kämpfenden Spielercharakter mit einem Bernsteinsamenbrötchen, während Ihr auf dem Deck des Luftsacks steht.", progress = "<Der prominente Todesritter seufzt.>", completion = "Haha! Ich hab doch GEWUSST, dass Ihr etwas vom Feiern versteht.\n\nIch bin schon viel besser gelaunt. Das war mit Abstand das Unterhaltsamste, was seit dem Mord an diesem Rüstmeister passiert ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[53932] = { id = 53932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweispaket: Libbiara Seuchenflucht", description = "Nugg hat bekommen, was Nugg wollte. Gebt dämlicher Blutelfe Getränk und sie verrät sich.\n\nBringt Paket zum Kommandanten. Nugg geht jetzt teure Häppchen kaufen.", sourceObjective = "Bringt das Beweispaket zu Kommandant Arlu Rabenpelz.\n\nBereitgestellter Gegenstand:", completion = "Hmm... Es würde mich nicht überraschen, wenn sie den Rüstmeister umgebracht hätte, nur um sich die Zeit zu vertreiben.\n\nFürs Erste können wir sie jedenfalls für die gefälschten Einladungen dingfest machen. Alles Weitere ergibt sich dann vor Gericht. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[53933] = { id = 53933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Shlae'garprozess", description = "Ich habe drei Haftbefehle ausgestellt. Nugg, Mollivox und Sharisanda nehmen gerade die Verdächtigen fest.\n\nUnser nächstes Ziel ist das Gericht.\n\nEs ist möglich, dass Ihr in den Zeugenstand gerufen werdet. Beantwortet die Fragen dann einfach so ehrlich wie möglich und überlasst den Rest den Mühlen der Justiz.", sourceObjective = "Gelangt im Shlae'garprozess zu einem Urteil.", completion = "Ich dachte eigentlich, alles läuft bestens... bis dann alles aus dem Ruder gelaufen ist.\n\nAber glücklicherweise haben wir eine neue Spur. Hört zu, {name}, unsere Arbeit ist noch nicht erledigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[53934] = { id = 53934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Hinweis aus Area 52", description = "Wir haben einen Brief aus Area 52 erhalten, dem Goblinaußenposten im Nethersturm. Der Verfasser behauptet, von der \"Situation in Shlae'gar\" zu wissen.\n\nMehr hat er oder sie nicht gesagt.\n\nIch bin hier mit Papierkram beschäftigt. Geht bitte Ihr dieser Spur nach und findet heraus, ob sich etwas Brauchbares ergibt.", sourceObjective = "Sucht in Area 52 im Nethersturm nach Hinweisen auf den Verfasser des Briefes.", completion = "Diese mysteriösen Betrüger mögen ja die Oberhand gewonnen haben, und womöglich sind sie sogar mit einem Mord davongekommen... Dennoch sollten sie sich nicht zu früh freuen, denn ich habe die Trumpfkarte!", sourceObjectiveStatus = "unverified-source-field" }
quests[53935] = { id = 53935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Rätsel lösen", description = "<Nobelflansch zieht eine Herausforderungskarte aus der Tasche.>\n\nDiese Karte habe ich einem der Angreifer abgenommen, als wir gegeneinander gekämpft haben! Damit könnt Ihr ihn bestimmt zu einer Art ultimativem Entscheidungskampf herausfordern!", sourceObjective = "Geht mit der mysteriösen Herausforderungskarte in die Shlae'gararena, um Boss Nobelflanschs Entführer zu stellen.", completion = "Ich war dort, {name}. Ich habe Euren Kampf gesehen.\n\nWir hatten diesen \"Beobachter\" seit dem Vorfall in Quel'Danas unter Verdacht, und wie es scheint, sind die Gerüchte wahr. Man beobachtet uns.\n\nIch werde diese Informationen an die zuständige Stelle weiterleiten. In der Zwischenzeit haben Boss Nobelflansch und ich eine angemessene Belohnung für Euch organisiert. Ich hoffe, sie gefällt Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[53936] = { id = 53936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pioniere aufhalten", description = "Das Eis sollte die Horde draußen halten, während wir uns um die auf dem Strand versammelten Pionierteams kümmern.\n\nIch werde diese Galeonen der Horde beschäftigen. Ihr müsst den Verantwortlichen ausschalten und alle Azeritbomben, derer Ihr habhaft werden könnt, zu mir bringen.\n\nDann entledigen wir uns ihrer Waffen.", sourceObjective = "Tötet Nebbik Megasprit, sammelt Azeritbomben ein und bringt sie zu Jaina oben auf dem Meerestor.", progress = "Konntet Ihr die Bomben an Euch bringen?", completion = "Die Meerestore haben das Herz des Tiragardesunds seit Generationen geschützt. Heute ist nicht der Tag, an dem die Angelpunktwerft fällt.\n\nWas diese Azeritbomben angeht... da habe ich eine Idee.", sourceObjectiveStatus = "unverified-source-field" }
quests[53937] = { id = 53937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Üb3r-Schrauber", description = "Es ist eine Schande, dass Gryzix sterben musste. Diese Typen von der Venture Co. werfen ein schlechtes Licht auf uns Unternehmer!\n\nWenigstens können wir immer noch den Bauplan für den Üb3r-Schrauber entschlüsseln. Reicht mir mal den Bauplan und den Dekodierer, dann haben wir das in Nullkommanix.", sourceObjective = "Wartet, bis Shuga Sprengkapp den Bauplan entschlüsselt.", completion = "Hier, {name}. Und jetzt lasst Eure Schöpfungen los!", sourceObjectiveStatus = "unverified-source-field" }
quests[53938] = { id = 53938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchs Nadelöhr", description = "Ihr könnt mich sehen?\n\nNa, da bin ich aber froh! Ich dachte, ich hätte mich in den Windungen der Zeit verirrt... mal wieder!\n\nAber um durch die Windungen des Zeitgefüges hindurchsehen zu können... müsst Ihr wahrhaftig ein äußerst begabter Schneider sein.\n\nWürdet Ihr mir dann vielleicht etwas Stoff bringen, <Schneider/Schneiderin>? Ich glaube, dann kann ich mit Eurer Hilfe herausfinden, wann genau ich mich gerade befinde, und das korrigieren.", sourceObjective = "Sammelt 5 Stücke gischtvernebeltes Leinen und 5 Stücke Tiefseesatin.", progress = "Wann in Azeroth bin ich...?", completion = "Ihr seid zurück! Das ging schnell... oder irre ich mich?", sourceObjectiveStatus = "unverified-source-field" }
quests[53939] = { id = 53939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorstoß nach Boralus", description = "Endlich! Es gibt keinen Ort in Kul Tiras, an dem die Allianz stärker vertreten ist. Wir müssen tapfer und unnachgiebig sein, wenn wir sie von hier vertreiben wollen.\n\nLok-tar ogar!", sourceObjective = "Führt den Angriff der Horde auf den Tiragardesund an.", completion = "Ich habe vernommen, dass Ihr in Boralus einen starken Eindruck hinterlassen habt, {name}... Vor allem am vorderen Tor! Ha!\n\nFür die Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[53940] = { id = 53940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Stich zur rechten Zeit", description = "Hm... Ich kann mich nicht erinnern, jemals zuvor in dieser Zeit gewesen zu sein.\n\nIch sollte Euch das wohl erklären. Mein Name ist Delormi und ich bin das letzte lebende Mitglied der Synchronschneider.\n\nWir stellen sicher, dass das Gewebe der Zeit – nun ja – intakt bleibt, aber ich habe gesehen, dass sich einige Risse aufgetan haben.\n\nTatsächlich glaube ich, das ist der Grund, warum ich in dieser Zeit angekommen bin. Vielleicht könntet Ihr mich dabei unterstützen, sie zu finden und zu schließen?", sourceObjective = "Unterstützt Delormi dabei, die Zeitrisse zu schließen.", completion = "Und das sollte es gewesen sein. Obwohl... Irgendetwas stimmt noch immer nicht...", sourceObjectiveStatus = "unverified-source-field" }
quests[53941] = { id = 53941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Mech für einen Goblin", description = "Gallywix hat einen Plan für die Auseinandersetzung mit der Allianz und hat um Eure Hilfe gebeten. Dabei geht es auch um das Azerit, das Ihr beschafft habt.\n\nSprecht mit ihm unten an der Bilgewasserbonanza und tut, was Ihr könnt, um ihm zu helfen... solange es um die Interessen der Horde geht.\n\nOh, und stellt sicher, dass Gallywix nicht stirbt. Die Allianz hat bereits versucht, ihn zu töten.", sourceObjective = "Trefft Euch mit Gallywix an der Bilgewasserbonanza.", completion = "Ihr seid hier! Gut, wir haben uns nämlich ein paar Probleme eingehandelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[53942] = { id = 53942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der richtige Mech für den Job", description = "Okay, {name}, wir sind bereit. Im G.M.O.D. ist genug Azerit, um einigen Ärger zu machen!\n\nWir müssen zu meiner, ähm, UNSERER Basis in Drustvar. Mekkadrill, dieser verflixte Gnomenkönig, greift unsere Azeritvorräte an!\n\nNachdem wir uns um die Basis gekümmert haben, kümmern wir uns um ihn! Ihr versteht, was ich sagen will?", sourceObjective = "Fliegt im G.M.O.D. nach Drustvar und verteidigt den Außenposten Krazzelfrazz.", completion = "Ihr und Gallywix habt uns gerettet! Hätte nicht gedacht, dass ich sowas mal über dieses Wackelkinn sagen würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[53943] = { id = 53943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Modularbau", description = "Auf dem Verlassenen Schrottplatz tummeln sich einige ziemlich gefährliche gnomische Konstrukte. Die Mechakerne, die sie enthalten, sind bei der Fertigung des Üb3r-Schraubers nützlich. Wenn man den Legenden glaubt, lassen sich damit Kreationen erschaffen, die es so noch nie gegeben hat!\n\nIhr seht abenteuerlustig aus, {name}. Was meint Ihr, habt Ihr Lust, ein paar Mechs zu verschrotten?\n\nVergesst nicht Euren Bogenlichtschraubenschlüssel!", sourceObjective = "Tötet mechanische Konstrukte beim Verlassenen Schrottplatz und repariert 8 Mechakerne mit einem Bogenlichtschraubenschlüssel.", sourceObjectiveStatus = "unverified-source-field" }
quests[53945] = { id = 53945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagaangriff!" }
quests[53947] = { id = 53947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Dünen", description = "Der Bauplan, den Ihr gefunden habt, ist verschlüsselt. Mit meinen Werkzeugen kann ich da nichts anfangen. Ich will nicht riskieren, die Daten zu beschädigen.\n\nAber ich kenne jemanden, der diese Nuss knacken kann: Datenguru Gryzix.\n\nWenn ich es richtig im Kopf habe, nimmt er sich in Vol'dun eine Auszeit am Strand, seit der Krieg ausgebrochen ist. Irgendetwas von wegen, niemand würde seine Arbeit würdigen.\n\nIhr könnt ihn aber bestimmt überzeugen, uns zu helfen.", sourceObjective = "Findet Datenguru Gryzix in den Vergessenen Marschen in Vol'dun.\n\nBereitgestellter Gegenstand:", completion = "Ugh, was wollt Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[53948] = { id = 53948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rachsüchtige Reise", description = "<Ihr hebt die Notiz auf und erkennt, dass die Venture Co. hinter dem Mord an Datenguru Gryzix steckt. Ihr durchsucht seine Leiche: Sein Dekodierer und der Bauplan für den Üb3r-Schrauber wurden gestohlen.\n\nIhr müsst seinen Dekodierer und den Bauplan finden und beides zurück zu Lotte Ebenkiel bringen, wenn Ihr den Üb3r-Schrauber bauen möchtet.\n\nDer Mech, der Euch folgt, könnte sich dabei als nützlich erweisen.>", sourceObjective = "Findet das Lager der Venture Co. und holt Gryzix' Dekodierer und den verschlüsselten Bauplan für Üb3r-Schrauber.", progress = "Alles klar, {name}? Hat Gryzix den Bauplan für Euch fertig gemacht?", completion = "Er ist tot? Armer Kerl, er war ein herausragender Ingenieur.\n\nIch danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53949] = { id = 53949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Üb3r-Schrauber", description = "Es ist eine Schande, dass Gryzix sterben musste. Diese Typen von der Venture Co. werfen ein schlechtes Licht auf uns Unternehmer!\n\nWenigstens können wir immer noch den Bauplan für den Üb3r-Schrauber entschlüsseln. Reicht mir mal den Bauplan und den Dekodierer, dann haben wir das in Nullkommanix.", sourceObjective = "Wartet, bis Lotte Ebenkiel den Bauplan entschlüsselt hat.", completion = "Hier, {name}. Und jetzt lasst Eure Schöpfungen los!", sourceObjectiveStatus = "unverified-source-field" }
quests[53950] = { id = 53950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosive Entlastung" }
quests[53951] = { id = 53951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosive Entlastung" }
quests[53952] = { id = 53952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu Tode gelangweilt", description = "Bis jetzt bin ich hier oben vor Langeweile fast gestorben. Ich glaube, wir brauchen etwas frisches Blut in der Arena. Manchmal geizt Boss Nobelflansch wirklich etwas zu sehr mit ihren Einladungen, meint Ihr nicht auch?\n\nIch habe von meinen Dienern ein paar nur geringfügig gefälschte Einladungen anfertigen lassen. Könntet Ihr mir nicht helfen, sie unters Volk zu bringen? Vor dem Auktionshaus in der Nähe der Feste Grommash sind immer jede Menge harte Kerle anzutreffen...", sourceObjective = "Benutzt das Schild der Shlae'gararena im Tal der Stärke in Orgrimmar.", completion = "Ihr habt das Schild aufgestellt? Gut. Jetzt müssen wir nur noch warten, bis die ersten Neulinge aufkreuzen.\n\nIch mag Euch, {name}. Ihr seid wie ich und scheut nicht davor zurück, im Interesse der eigenen Unterhaltung |cFF0000FFdas ein oder andere Verbrechen zu begehen.|r", sourceObjectiveStatus = "unverified-source-field" }
quests[53953] = { id = 53953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shlae'gar wartet auf Euch!", description = "Seid Ihr es auch leid, Euch im langweiligen alten Tal der Stärke Löcher in den Bauch zu stehen? Dann kommt in die Shlae'gararena und kämpft zur Belustigung des Publikums!\n\nVielleicht gewinnt Ihr, vielleicht werdet Ihr dabei getötet. Aber eines ist sicher: Ihr werdet jede Menge Spaß haben!\n\nHolt Euch eine Einladung und bringt sie Skuglor in der Nähe des Vordereingangs. Die Shlae'gararena erwartet Euch schon!", sourceObjective = "Bringt eine Einladung in die Shlae'gararena.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[53955] = { id = 53955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsfront: Die Schlacht um die Dunkelküste", description = "Die Dunkelküste gehört der Horde! Wir müssen die Stellung halten, um unsere Vormacht in Kalimdor zu verteidigen.\n\nBereitet Euch auf einen Kampf vor.", sourceObjective = "Besiegt die Allianz in der Schlacht um die Dunkelküste.", completion = "Gut gekämpft, {name}, obwohl es sicher nicht lange dauern wird, bevor die Allianz versucht, die Dunkelküste zurückzuerobern. Wenn sie das tut, werden wir kampfbereit sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[53957] = { id = 53957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekruten der Dunkelküste", description = "Wir haben einige wenige Rekruten, die uns bei der Rückeroberung der Dunkelküste helfen können.\n\nDoch zunächst muss das Urtum des Krieges sich wieder bester Gesundheit erfreuen. Um ihm zu helfen, müssen wir ihm Ressourcen spenden. Das wird es wieder aufleben lassen!\n\nSobald das Urtum des Krieges wiederhergestellt ist, sprecht mit Jarod Schattensang und rekrutiert eine Einheit. Ich bin sicher, dass es sehr lehrreich für sie sein wird, an Eurer Seite zu kämpfen.", sourceObjective = "Stellt das Urtum des Krieges wieder her und sprecht danach mit Jarod Schattensang, um einen Verbündeten zu rekrutieren.", completion = "Ist es nicht schön, wenn einem ab und zu Leute folgen?", sourceObjectiveStatus = "unverified-source-field" }
quests[53959] = { id = 53959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufgerüstete Armee", description = "Wir müssen sicherstellen, dass unsere Soldaten die bestmögliche Ausrüstung im Kampf gegen die Horde zur Verfügung haben.\n\nSobald die Jägerhalle fertig ist, sprecht mit Cordressa Dornenbogen darüber, wie die Waffen und Rüstungen unserer Trupps verbessert werden können.", sourceObjective = "Sprecht mit Cordressa Dornenbogen, um zu erfahren, was die Jägerhalle zu bieten hat.", completion = "Wie steht es um Euer Rüstzeug?", sourceObjectiveStatus = "unverified-source-field" }
quests[53960] = { id = 53960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Altar der Alten", description = "Jetzt, da die Spenden in vollem Gange sind, wurde der Altar der Alten wiedererrichtet.\n\nGeht und sprecht mit Mondpriesterin Lasara und lasst Euch erklären, was der Altar zu bieten hat.", sourceObjective = "Sprecht mit Mondpriesterin Lasara und lasst Euch erklären, was der Altar der Alten zu bieten hat.", completion = "Mit derartiger Macht zu unserer Verfügung könnten wir vielleicht eine Chance haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[53961] = { id = 53961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glevenwerk, Meisterwerk", description = "Wir alle sind seit Teldrassil etwas angespannt, aber Erion hat es besonders schwer getroffen. Er hat die erste Chance zu helfen mit beiden Händen ergriffen.\n\nWieso sprecht Ihr nicht mit ihm und findet heraus, was er da im Glevenwerk auf die Beine stellt?", sourceObjective = "Sprecht mit Erion und erfahrt, was das Glevenwerk zu bieten hat.", completion = "Diese Gleven werden mit den Azerit-Mech-Monstrositäten kurzen Prozess machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53962] = { id = 53962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus demselben Stoff", description = "Mein unendliches Ich hatte recht. Ich kann die Zeit nicht länger weben.\n\nEs wurden zu viele meiner Fäden durchtrennt. Ich kann keine anderen Fäden fühlen.\n\nIch bin jetzt alleine und habe keine Fäden mehr. Ihr seid es aber nicht.\n\nNehmt dieses Muster. Ihr habt Euch als <talentierter Schneider/talentierte Schneiderin> Eurer eigenen Zeit erwiesen und als <Retter/Retterin> für so viele andere.\n\nDas Gewebe der Zeit braucht Eure Hände, um weiter gewebt zu werden. Ich vertraue Euch diese verantwortungsvolle Aufgabe an.\n\nSprecht mit mir, wenn Ihr bereit seid. Ich bringe Euch in die Zeit zurück, in der all das angefangen hat.Ihr erlernt:", sourceObjective = "Bittet Zeitweberin Delormi, Euch in Eure Zeit zurückzubringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53963] = { id = 53963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagaangriff!" }
quests[53965] = { id = 53965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kinderwoche", description = "Ich danke Euch für Euer Angebot bei der Kinderwoche zu helf'n, {name}. Wir ham 'n kleines Mädchen hier, das gerne Zandalar erforsch'n möchte!\n\nNehmt diese Pfeife. Damit könnt Ihr das Kind ruf'n, um das Ihr Euch in dieser Woche kümmern wollt. Nach der Kinderwoche hat sie keinen Nutz'n mehr.\n\nWenn Ihr bereit seid, dann benutzt die Pfeife. Trefft Euren neuen Schützling. Sie kann's kaum erwart'n, Euch kenn'nzulern'.", sourceObjective = "Benutzt die Pfeife des Zandalariwaisenkinds, um Euren Schützling zu rufen, um den Ihr Euch während der Kinderwoche kümmern werdet.\n\nBereitgestellter Gegenstand:", completion = "Wer seid Ihr? Ich bin Azala.\n\nMutta und Vatta sin' gestorb'n, als ich noch sehr klein war. Seitdem leb ich hier mit den andren kastenlosen Kindern. \n\nWir gehör'n keiner Kaste an und deswegen is' es für uns schwer, 'n gutes Leb'n zu leb'n, wenn wir groß sin'. Ohne Verbindung zu 'nem Loa oder gut kämpf'n zu könn'n sind wir auf uns allein gestellt.\n\nIch bin keine gute Kämpferin, aber ich mag die Loa. Zeigt mir Zandalar und besucht mit mir 'n paar Loa, damit ich rausfinde, wem ich folg'n will!", sourceObjectiveStatus = "unverified-source-field" }
quests[53966] = { id = 53966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loa der Winde", description = "Ich hab gehört, dass Pa'ku irgendwo in Zuldazar lebt. Ihre Priester erzähl'n Geschichten über sie, wenn sie unsre Halle der Kasten besuch'n.\n\nSie is' 'n sehr beliebter Loa. Ich mein, sie beherrscht den Himmel UND das Meer. Das is' ganz schön viel Blau und Blau is' meine Lieblingsfarbe!\n\nVielleicht könnt ich 'ne Anhängerin von ihr werd'n?", sourceObjective = "Bringt Azala zur Pterrorhöhe in Zuldazar. Ruft sie zu Euch, falls sie nicht anwesend sein sollte, wenn Ihr ankommt.", completion = "Ich bin mir nich' sicher, {name}. Die Pterrorhühner sind schon hübsch, aber ich weiß nich', ob ich große Höhen wirklich mag.", sourceObjectiveStatus = "unverified-source-field" }
quests[53967] = { id = 53967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Froschmarschen", description = "Die Betreuer erzähl'n uns immer Geschichten in der Halle der Kasten. Manchmal warn'n die uns vor Gefahren und manchmal geht es um die Loa... aber fast immer gibt's 'ne Lehre in der Geschichte.\n\nEinmal ham sie uns von Krag'wa erzählt und wie die Bluttrolle seine Anhänger getötet ham und dass er seitdem verschwunden is'.\n\nIch hab gehört, dass er zurück is'! Er is' wieder in Nazmir und er plant seine Rache gegen die Bluttrolle.\n\nKönn'n wir zu ihm geh'n?", sourceObjective = "Bringt Azala zu Krag'was Höhle in den Froschmarschen in Nazmir. Ruft sie zu Euch, falls sie nicht anwesend sein sollte, wenn Ihr ankommt.", completion = "Wenn ich Krag'wa folgen würde, würde er mich auffress'n? Oder nich'?\n\nDas will ich gar nich' wiss'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[53968] = { id = 53968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das wandelbare Rudel", description = "Ein Loa interessiert mich besonders: Gonk! Ich hab die Priester sag'n hör'n, dass er der freundlichste der Loa is'. Er lässt seine Anhänger sogar andere Loa anbet'n!\n\nAber das Beste is', dass er und seine Anhänger sich in verschiedene Gestalt'n verwandeln könn'n. Das will ich auch!\n\nKönnt Ihr mich zu ihm bring'n?", sourceObjective = "Bringt Azala zur Höhle von Gonk im Garten der Loa in Zuldazar. Ruft sie zu Euch, falls sie nicht anwesend sein sollte, wenn Ihr ankommt.", completion = "Habt Ihr geseh'n, wie Gonk mich in all diese Gestalten verwandelt hat?\n\nVielleicht kann ich das eines Tages selbst mach'n!", sourceObjectiveStatus = "unverified-source-field" }
quests[53969] = { id = 53969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd nach Gold", description = "Ich weiß, dass es bei dieser Reise eigentlich um die Loa geh'n soll...\n\nAber ich will die Goldinsel seh'n!\n\nIch hab Geschichten von untoten Piraten gehört und über 'ne Insel, die von Goldmünzen und Schätzen übersät is'! Könn'n wir uns das bitte anseh'n?! \n\nBitteeeeeeeee?", sourceObjective = "Bringt Azala zur Goldenen Insel in Vol'dun. Ruft sie zu Euch, falls sie nicht anwesend sein sollte, wenn Ihr ankommt.", completion = "Es is' nich' einfach, dieses ganze Glitzerzeug dazulass'n, aber die Flüche sind wirklich fieser Voodookram!", sourceObjectiveStatus = "unverified-source-field" }
quests[53970] = { id = 53970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Königin der Sethrak", description = "Die Betreuer erzähl'n immer davon, dass die Sethrak Karawanen angreif'n... aber sie erzähl'n auch, dass die Sethrak und die Zandalari früher Freunde war'n!\n\nIch hab gehört, es gibt 'n paar Sethrak, die immer noch Freunde sein woll'n, und dass sie 'nen Loa ham, der Frieden mehr will als alles andre!\n\nKönnt Ihr mich zu den Sethrak und ihrem Loa bring'n? Ich will sie selbst mal treff'n!", sourceObjective = "Bringt Azala zur Terrasse der Ergebenen in Vol'dun. Ruft sie zu Euch, falls sie nicht anwesend sein sollte, wenn Ihr ankommt.", completion = "Sethraliss is' wohl sehr weise... aber auch sehr gruselig.\n\nSeid Ihr sicher, wir könn' nich' zum Glitzerzeug zurück?", sourceObjectiveStatus = "unverified-source-field" }
quests[53971] = { id = 53971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zur Halle der Kasten", description = "Ich kann's kaum glaub'n, dass wir so viele Orte geseh'n ham. Davor bin ich noch nich' mal aus Zuldazar rausgekomm'n!\n\nIch hab vielleicht keine Kaste, aber jetz', da ich so viele Loa getroff'n hab, kann ich vielleicht einem von ihnen folg'n und hab dann nich' mehr nur 'n Leben auf der Straße vor mir.\n\nJetzt sollt'n wir aber in die Halle der Kasten zurückkehr'n. Die Betreuer werd'n schon auf mich wart'n.", sourceObjective = "Bringt Azala zurück zur Halle der Kasten in Zuldazar. Ruft sie zu Euch, falls sie nicht anwesend sein sollte, wenn Ihr ankommt.", progress = "Wartet nur, bis die andren von meiner Reise hör'n!", completion = "Dies'n Ort hab ich irgendwie vermisst.", sourceObjectiveStatus = "unverified-source-field" }
quests[53973] = { id = 53973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rausfliegen und Draufhauen", description = "Wir müssen unsere Krieger vor der Armee der Allianz verteidigen, während wir uns das Azerit holen.\n\nNehmt die Azeritwaffen, die Ihr gestohlen habt, und ladet sie in einen dieser Gyrokopter.\n\nMisha und ich werden uns aufmachen und vom Boden aus gegen die Verstärkung kämpfen, während Ihr uns Luftunterstützung gewährt.\n\nWir müssen sie so lange aufhalten, bis unsere Krieger mit dem Azerit abgezogen sind.", sourceObjective = "Fliegt den Goblingyrokopter und wehrt die Armee der Allianz ab.", completion = "Ihr habt Euch gut geschlagen! Wir haben den Sieg davongetragen und die Allianz wurde geschwächt.", sourceObjectiveStatus = "unverified-source-field" }
quests[53974] = { id = 53974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Druiden vom Düsterseestrand", description = "Die latente Macht am Düsterseestrand bietet uns die Möglichkeit, uns große Macht nutzbar zu machen. Edgard, einer unserer Verbündeten, verfügt über umfangreiches Wissen darüber, welche Auswirkungen das auf unsere Bemühungen haben könnte.\n\nSucht ihn auf und entdeckt die Macht der Natur.", sourceObjective = "Nehmt den Düsterseestrand ein und sprecht dann mit Edgard, um herauszufinden, was er zu bieten hat.", progress = "Habt Ihr etwas herausgefunden?", completion = "Unser Feind hat kaum eine Chance, wenn wir eine derartige Macht auf unserer Seite haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[53975] = { id = 53975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachtflug", description = "Jetzt, da das Eschenwaldlager in unserer Hand ist, wird es viel einfacher sein, über das Schlachtfeld zu reisen.\n\nIch habe Pläne für ein Flugnetzwerk ausgearbeitet, die wirklich großartig sind, wenn ich das so sagen darf. Ihr scheint nicht sehr beschäftigt zu sein. Nehmt meine Notizen und bringt sie sofort zu unserem Kommandanten.\n\nSprecht mit Fidelio und er wird Euch einen Hippogryphen zur Verfügung stellen.", sourceObjective = "Bringt Schattenfalls Notiz zu Eurem Kommandanten in Bashal'Aran.", completion = "Ausgezeichnete Arbeit. Wobei Mordents übertriebener Bericht, was seine Rolle bei der Eröffnung des Himmels für uns anging, unnötig war.", sourceObjectiveStatus = "unverified-source-field" }
quests[53976] = { id = 53976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisenbestand", description = "Das wird so nichts! Wir müssen Eisen sammeln, wenn wir überhaupt irgendetwas gegen die Horde erreichen wollen.\n\nGeht zu den Ruinen von Lornesta und schnappt Euch das Eisen. Wir brauchen es!", sourceObjective = "Sammelt Eisen aus einer Erzkiste in der Nähe.", progress = "Wir müssen dieses Eisen einsammeln!", completion = "So muss das sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[53977] = { id = 53977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kriegskasse", description = "Willkommen an der Kriegsfront, {name}! Endlich geht es zur Sache. \n\nAlle Ressourcen, die wir zusammengetragen haben, kommen in die Kriegskasse. Sobald sich dort genug angesammelt hat, könnt Ihr Euch bedienen!\n\nWieso schaut Ihr nicht mal vorbei und seht, was Ihr findet?", sourceObjective = "Beschafft Ressourcen aus der Kriegskasse in Bashal'Aran.", progress = "Habt Ihr etwas von den Ressourcen aus der Kriegskasse bekommen?", completion = "So muss das sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[53978] = { id = 53978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pulverpläne", description = "Nachdem alle Zeppeline der Horde von der Lordadmiralin vereist wurden, rudern die Schufte jetzt durch das Meerestor herein.\n\nDiese hübsche, schmale Meerenge, die einen großartigen Flaschenhals bildet.\n\nIch lasse von meinen Leuten eine Kanone und etwas Munition dort hinschleppen. Wenn Ihr etwas Schießpulver einsammelt, sind wir hinter dem Tor bestens gerüstet. Dort werden sie einen Angriff nicht erwarten.\n\nWir schicken die Horde auf den Grund des Hafens!", sourceObjective = "Sammelt 6 Pulverfässer.", progress = "Habt Ihr genug Schießpulver gefunden?", completion = "Ausgezeichnet! Wir sind bestens darauf vorbereitet, die Boote der Horde auszuschalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[53979] = { id = 53979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagaangriff!" }
quests[53981] = { id = 53981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ruhmreicher Tag", description = "Der Großteil unserer Krieger hat überlebt und wir haben das Azerit und die Waffen der Allianz gesichert.\n\nSeid stolz auf Euch, {name}. Ihr habt heute ehrenhaft gekämpft.\n\nGeht und berichtet Nathanos von unserem Sieg hier. Das Azerit sollte bald bei ihm eintreffen.", sourceObjective = "Kehrt zu Nathanos Pestrufer an Bord der Klagelied zurück.", completion = "Ich habe von Eurem Sieg gehört. Gut gemacht. Die Allianz wird sich von dieser Niederlage nicht so schnell erholen.\n\nDas Azerit wird in diesem Moment für unseren nächsten Angriff vorbereitet. Die Dunkle Fürstin geht davon aus, dass Ihr bereit seid, zu helfen, wenn die Zeit kommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[53982] = { id = 53982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte von den Entfesselten", description = "Eure Unterstützung hat uns Hoffnung gegeben. Euer Mut hat uns Stärke verliehen.\n\nDurch Euch haben wir eine völlig neue Vision unserer Zukunft, {name}.\n\nDafür werden wir Euch auf ewig dankbar sein.\n\nIch hoffe, wir können Euch auch weiterhin all das vergelten, was Ihr für uns getan habt!", sourceObjective = "Sprecht mit Atolia Seeperl in Neuheim über Eure Belohnung.", completion = "Ihr schlagt Euch hervorragend!\n\nGemeinsam sind wir stark!", sourceObjectiveStatus = "unverified-source-field" }
quests[53983] = { id = 53983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nasse Sache: Fortneid" }
quests[53986] = { id = 53986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruhe vor dem Sturm", description = "Auf ein Wort, {name}.\n\nEs gab einen Überfall auf das Anwesen der Norwinsens, wo wir einige neue Azeritsysteme getestet haben. Lady Jaina bat den SI:7 darum, sich die Sache einmal anzusehen. Ich habe den Bericht hier.\n\nIch weiß, dass die Prachtmeerfamilie etwas Zeit gemeinsam verbringen möchte, bevor sie wieder auseinandergerissen wird, aber der Krieg tobt immer noch.\n\nIhr wart immer ein Freund der Familie. Bringt den Bericht zu Jaina. Ich glaube, sie wollten dem Familiendenkmal ihre Aufwartung machen.", sourceObjective = "Bringt den Bericht des SI:7 zu Lady Jaina.", completion = "Noch ein Angriff! Die Horde wird dreist. Ich kann das nicht hinnehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53988] = { id = 53988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestade des Schicksals", description = "So sei es. Ihr seid <ein besserer Verbündeter/eine bessere Verbündete> als jede Armee, die Wrynn geschickt hätte.\n\nWir werden die Dunkelküste zusammen einnehmen, aber zuerst müssen wir Tyrande finden. Ohne ihre Hilfe werden unsere Streitkräfte von der Horde überrannt.\n\nEs ist noch nicht lange her, dass sie mit einer kleinen Truppe in Richtung Zoramstrand aufgebrochen ist. Wenn wir uns gleich auf den Weg machen, finden wir sie vielleicht noch vor der Horde.", sourceObjective = "Nehmt das Sturmwindportal nach Darnassus und trefft Euch mit Maiev Schattensang am Zoramstrand im Eschental.", completion = "Es scheint, als wäre unsere eigensinnige Priesterin fleißig gewesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53989] = { id = 53989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoffnung", description = "Nein... unmöglich. So wäre sie niemals gestorben!\n\nSucht am Strand nach Hinweisen auf ihren Aufbruch. Persönliche Dinge. Waffen. Alles, was Ihr finden könnt.\n\nTyrande ist immer noch da draußen, {name}. Wir dürfen die Hoffnung nicht aufgeben.", sourceObjective = "Sucht nach Hinweisen auf Tyrande.", progress = "Irgendein Lebenszeichen?", completion = "Wenn sie getötet worden wäre, hätte man das nicht so sorgfältig beiseitegelegt. Sie ist am Leben!", sourceObjectiveStatus = "unverified-source-field" }
quests[53990] = { id = 53990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In dunkelster Nacht", description = "{name}, ich will offen mit Euch sein. Tyrande riskiert törichterweise ihr Leben mit dem Ritual, das sie abhalten will. Wenn sie fällt, waren auch all unsere Kriegsanstrengungen vergebens.\n\nWir müssen zur Dunkelküste aufbrechen und ihr zu Hilfe kommen. Nur dann können wir weiter vorrücken und unser Heimatland zurückerobern.\n\nWir haben Teldrassil verloren. Auch wenn sie eine Närrin sein mag, unser Volk würde den Verlust von Tyrande nur schwer verkraften.", sourceObjective = "Findet Tyrande an der Dunkelküste und helft ihr.", completion = "Unsere Rache hat gerade erst begonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53992] = { id = 53992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsfront: Die Schlacht um die Dunkelküste", description = "Wir werden keine weiteren Übergriffe der Horde auf unsere Gebiete dulden.\n\nDie Nachtelfen werden heute nicht allein kämpfen. Die Dunkelküste wird erneut ihnen gehören.\n\nFür die Allianz!", sourceObjective = "Besiegt die Horde in der Schlacht um die Dunkelküste.", progress = "Die Dunkelküste wird wieder unser sein.", completion = "Ihr habt den Tag gerettet, aber der Krieg ist noch lange nicht vorbei.\n\nFür die Allianz!", sourceObjectiveStatus = "unverified-source-field" }
quests[53993] = { id = 53993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Stimme im Wind", description = "<Eine entfernte, mysteriöse Stimme durchdringt Euren Geist.>\n\nMeine Verzauberungen sind nicht verloren...\n\nFindet mich...\n\nDrustvar...\n\nFallhafen...", sourceObjective = "Findet den Ursprung der mysteriösen Stimme in Drustvar.", completion = "Sorgt Euch nicht, mein Freund. Ich werde Euch nichts tun. Aber ich habe ein Angebot für Euch.\n\nIch war nämlich einst eine Druidin, und das Einzige, was ich noch mehr liebte als die Pflege des Waldes und seiner Lebewesen, war die Verzauberkunst.\n\nAber dann wurde ich ermordet und dazu verflucht, über diese Halbinsel zu wandern, ohne den Fluss oder die Berge überqueren zu können, solange mein Körper noch existierte.\n\nWenn Ihr meinen alten Körper zerstört und mir helft, einen neuen zu erschaffen, werde ich Euch zeigen, wie man die Verzauberungsrute herstellt, die Ihr entzaubert habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[53994] = { id = 53994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagaangriff!" }
quests[53995] = { id = 53995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Taurengerber", description = "Hey, Zastamann.\n\nEiner Eurer Tauren war hier und hat gefragt, wer der beste Lederverarbeiter is', den ich kenne, der sich nich' davor scheut, sich die Hände schmutzig zu mach'n.\n\nIch hab ihm Euern Namen gegeb'n und er hat mich gebet'n, 'n Treff'n zu arrangier'n. Hat gesagt, er wartet im Basar an den Docks.\n\nEr hat nich' gesagt, wofür er <meinen best'n Schüler/meine beste Schülerin> braucht, aber so, wie er sich verhalt'n hat, muss es was Großes sein.\n\nGeht runter zu den Docks und sucht nach dem Tauren. Zeigt ihm, was ich Euch beigebracht hab.\n\nUnd immer schön konzentrier'n! Woll'n ja nicht, dass Ihr mich schlecht aussehen lasst!", sourceObjective = "Trefft den taurischen Lederverarbeiter im Hafen von Zandalar.", completion = "Der Erdenmutter sei Dank!\n\nWir haben viel zu besprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53996] = { id = 53996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stöckchen holen", description = "Damit meine Verzauberung funktionieren kann, benötigen wir Holz aus diesem Wald.\n\nAls ich noch am Leben war, bin ich durch diesen Wald gewandert und habe mich um die Bäume gekümmert. Diese Bäume sind zwar schon lange verschwunden, aber vielleicht kennen ja die Abkömmlinge ihrer Schösslinge meine Geschichte und sind bereit zu helfen.\n\nAber fällt bloß keine Bäume! Bitte nicht! Da draußen gibt es Holzfäller, die ohne Rücksicht auf die Natur den Wald roden. Beraubt sie und bringt sie um den Lohn ihrer harten Arbeit. Vielleicht wird ihnen das eine Lehre sein, diese Bäume in Frieden zu lassen.\n\nBringt mir so viel Holz, wie Ihr zusammentragen könnt.", sourceObjective = "Sammelt 9 Bündel Hartholz.", progress = "Ich vermisse die Stimmen des alten Waldes.", completion = "Ausgezeichnet! Dieses Holz scheint ganz frei von Befall und Verrottung zu sein. Und weder zu lang noch zu kurz. Mit dem nötigen Druck kann man es gerade noch biegen. Es ist perfekt geeignet!", sourceObjectiveStatus = "unverified-source-field" }
quests[53997] = { id = 53997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der sechste Sinn", description = "Damit mein Plan funktionieren kann, müssen wir den Zauber brechen, der auf meinen Überresten liegt und der meinen Geist an diesen Ort fesselt.\n\nMeine sterblichen Überreste befinden sich tief im Inneren dieses Waldes. Dort gibt es Zauberschutze, die Geister einfangen sollen, die noch immer in der materiellen Welt verankert sind. Sobald meine Überreste geläutert sind, kann ich frei durch die Wälder streifen.\n\nBis dahin muss ich Euch bitten, alle Zauberschutze auf dem Weg zu entzaubern.\n\nSprecht mich an, wenn Ihr bereit seid. Ich werde Euch dann zu meinem Grab führen.", sourceObjective = "Geleitet Sef Iwen zu ihrem Grab.", completion = "Gute Arbeit!\n\n<Sef schaut einen Moment lang nachdenklich drein.>\n\nIch habe Euch wohl noch gar nicht meinen Plan verraten.", sourceObjectiveStatus = "unverified-source-field" }
quests[53998] = { id = 53998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exhumiert", description = "Wie gesagt kann ich nicht mit der materiellen Welt interagieren.\n\nIch kann Lebewesen dominieren und damit die Kontrolle über ihre Körper erlangen, aber ich finde das unzumutbar. Denn es bedeutet nichts anderes als die Versklavung der armen Kreatur.\n\nWas ich will, ist ein eigener Körper. Wenn Ihr einen Golem erschaffen und beleben könnt, wäre dieser zunächst ohne jegliche Intelligenz. Eine Hülle, derer ich mich problemlos bemächtigen könnte.\n\nAber dazu darf meine Seele nicht anderweitig in dieser Welt verankert sein. Ihr müsstet also den Zauber aufheben, der meinen Geist an meine sterblichen Überreste bindet.", sourceObjective = "Läutert Sef Iwens Überreste.", progress = "Wenn ich mein altes Ich so anschaue, werde ich schon etwas nostalgisch.", completion = "Es fühlt sich so... anders an.\n\nAls wäre ich in der Mitte eines riesigen, absolut dunklen Raums. Nicht wortwörtlich, aber ich habe das Gefühl, als würde gleich außerhalb meiner Sichtweite etwas... Beunruhigendes lauern.\n\nZumindest muss ich mir keine Sorgen mehr über diese Geisterfallen machen.\n\nUnd jetzt, da der Zauber, der mich an meine Überreste gefesselt hat, aufgehoben ist, hält uns hier nichts mehr. Lasst uns nach Süden weiterreisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53999] = { id = 53999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seidiges Haftmittel", description = "Unser nächstes Ziel befindet sich in der Nähe von Gol Koval. Aber auf dem Weg dorthin könntet Ihr etwas für mich einsammeln.\n\nIch selber hasse die Dinger und traue mich kaum, Euch zu fragen, aber die Widerstandsfähigkeit ihrer Spinnennetze, die sie überall hinweben, ist tatsächlich einzigartig.\n\n<Sef verzieht das Gesicht bei diesem Gedanken.>\n\nIm Südosten von hier leben Spinnen. Als Wächterin der Natur möchte ich Euch nicht bitten, sie zu töten, aber wenn Ihr... frische Seide von ihnen \"besorgen\" könntet, hätten wir ein Mittel, um die Gliedmaßen des Golems zusammenzuhalten.", sourceObjective = "Sammelt 55 Teile unverwüstliche Spinnenseide.", progress = "Habt Ihr die Seide bekommen?", completion = "<Sef schüttelt sich vor Abscheu.>\n\nBäh! Der Gedanke, dass dies ein Teil meines Körpers sein soll, lässt mich meine Bitte fast bedauern.\n\nAls Druidin erklärte man mir, dass alle Dinge der Natur Schönheit bergen, aber für mich zählen diese dünnbeinigen Monstrositäten nicht dazu.\n\nGehen wir weiter. Ich möchte mich nicht in ihrer Nähe aufhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[54000] = { id = 54000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herzschlagfinale", description = "Wir haben jetzt die meisten Materialien, die wir benötigen, aber es fehlt noch eine entscheidende Sache: ein Herz.\n\nKeine Sorge. Ich meine nicht eins aus Fleisch, sondern aus Stein, um die Materialien des Körpers zu einer einheitlichen Gestalt zu formen.\n\nFindet einen glatten Stein und verzaubert ihn so, dass er Lebenskraft birgt. Dazu braucht man mächtige Reagenzien, aber ein mächtiger Verzauberer wie Ihr hat diese gewiss dabei oder weiß, wo man sie finden kann.\n\nWenn das erledigt ist, muss der Stein aufgeladen werden. Die Seelen, die die Elementare und die Untoten hier beleben, sollten sich dafür eignen.", sourceObjective = "Erschafft einen Runenmachtkern und ladet ihn mithilfe der Leichen der erweckten Wächter und rachsüchtigen Knochen auf.", completion = "Das war der letzte Gegenstand, den wir gebraucht haben.\n\nJetzt müssen wir uns nur noch in mein Sanktum begeben, um alles ungestört zusammensetzen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[54001] = { id = 54001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir gehen rein", description = "Dies war einst ein Schrein der Drust. Es gibt eine Reihe von Siegeln, die es uns bei richtigem Gebrauch ermöglichen, uns zurück in mein altes Sanktum zu teleportieren.\n\n<Sef schaut sich etwas verwirrt um und räuspert sich dann.>\n\nEs ist schon Jahrhunderte her, seit ich das letzte Mal hier war. Ich bin mir nicht ganz sicher, in welcher Reihenfolge die Siegel aktiviert werden müssen, um das Portal zu öffnen.\n\nIch hoffe, Ihr seid etwas abenteuerlustig. Oh, und seid vorsichtig. Ich habe die Runen so verzaubert, dass sie Eindringlinge mit Gewalt fernhalten.", sourceObjective = "Aktiviert die Teleportationsrunen, um zu Sefs Unterschlupf zu gelangen.", completion = "Trautes Heim, Glück allein!", sourceObjectiveStatus = "unverified-source-field" }
quests[54002] = { id = 54002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das große Ganze", description = "Hm... Es sieht alles unberührt aus.\n\nDa drüben können wir mit dem Bau meines neuen Körpers beginnen. Danach zeige ich Euch, wie man meine Verzauberungsrute anfertigt.\n\n<Sef scheint sich sehr zu freuen und strahlt Euch an.>", sourceObjective = "Setzt den Golem für Sef Iwen zusammen.", progress = "Darauf habe ich seit langer Zeit gewartet.", completion = "<Sef sieht Euch entsetzt und niedergeschlagen an.>\n\nIch... Wir könnten es noch einmal versuchen, aber... ich glaube, das ist ein Zeichen... Ihr seid auch ohne mich in der Lage, den Leuten in der Not zu helfen. Vielleicht ist es für mich an der Zeit weiterzuziehen.\n\n<Sefs besorgtes Gesicht zeigt ein kleines Lächeln.>\n\nIch werde Euch für Eure Hilfe auf ewig dankbar sein. Ich habe zwar jetzt keinen Körper, aber dank Euch benötige ich auch keinen mehr.\n\nBevor ich gehe, will ich Euch noch zeigen, wie man meine Verzauberungsrute anfertigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[54004] = { id = 54004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testlauf Nr. 1: Mech gegen Mekkadrill", description = "Also schön, wir haben MEHR als genug Azerit in diesem Baby, um Mekkadrill und sein Luftschiff in die Luft zu jagen.\n\nDiese radioaktive Ausgeburt wird dafür bezahlen, seine Spielzeuge loszuschicken, um einen MEINER, ähm, UNSERER Stützpunkte anzugreifen.\n\nSpringt rein, {name}. Wir müssen einen Gnom in die Luft sprengen.", sourceObjective = "Besteigt mit Gallywix den G.M.O.D. und stellt Mekkadrill.", completion = "Hier ist das letzte Goblinwort noch nicht gesprochen... und ich habe immer das letzte Wort!", sourceObjectiveStatus = "unverified-source-field" }
quests[54005] = { id = 54005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wissen der Drust", description = "Ahoi, {name}!\n\nWenn Ihr einen Moment Zeit habt, könnte ich Eure Hilfe brauchen. Ich habe vor Kurzem eine große Lieferung Drustrelikte erhalten, die ich verarbeite.\n\nDie meisten Stücke davon waren nichts Besonderes, aber eines dafür umso ungewöhnlicher. Allein schon wenn ich es halte, bekomme ich eine Gänsehaut.\n\nIhr seid <mein bester Schüler/meine beste Schülerin> und vielleicht wäre es ja ganz interessant, wenn wir es zusammen entzaubern, um zu sehen, wie es erschaffen wurde.\n\nWas meint Ihr dazu?", sourceObjective = "Entfernt vorsichtig die Verzauberung von dem uralten Drustrelikt, um seine Beschaffenheit zu ermitteln.", completion = "Tut mir leid, {name}, ich hätte nicht gedacht, dass die Verzauberung so komplex ist. Ich dachte, ich könnte die Zauberformel bewahren.\n\n\n\nDas war's dann wohl. Durch die Zerstörung des Reliktes wird uns die Formel dahinter verborgen bleiben.\n\nDas ist wirklich eine Schande. Es kommt nicht oft vor, dass ein anderer Verzauberer mich so blöd aussehen lässt.", sourceObjectiveStatus = "unverified-source-field" }
quests[54006] = { id = 54006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine neue Hoffnung", description = "Die Dunkelküste gehört wieder unserem Volk, wozu Ihr einen bedeutenden Teil beigetragen habt. Und obwohl ich mit ihren Methoden nicht einverstanden bin, hätten wir es ohne Tyrande nicht geschafft.\n\nUngeachtet unserer Differenzen ist sie immer noch unsere Anführerin... und eine Inkarnation der Nachtkriegerin höchstpersönlich.\n\nSie wird gleich beginnen. Ihr könnt hier an meiner Seite stehen.", sourceObjective = "Wohnt Tyrandes Ansprache an die Kaldorei bei.", completion = "Dori'thur legte dieses Ei, als Elunes Schatten auf uns fiel. Wenn Ihr willens seid, möchte ich ihren Nachwuchs als Zeichen des Dankes in Eure Obhut geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[54007] = { id = 54007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versicherungspolice", description = "Mekkadrill nennt UNS Idioten, hat man dafür Worte? Na, wenn ich ein Idiot bin, warum habe ich dann eine Versicherung auf meinen Mech abgeschlossen, hm?\n\nIch wette, dieser verstrahlte Dummkopf hat SEINEN Mech nicht versichert!\n\nWir werden hier in null Komma nichts raus sein. Ich muss nur noch schnell den Pannendienst rufen, damit er herkommt und das Ding hier repariert.\n\nBitte drückt in meinem Mech den Knopf für den Pannendienst.\n\nAber, äh... drückt bloß nicht den falschen.", sourceObjective = "Drückt den Pannendienstknopf im G.M.O.D.", completion = "Vielleicht hätte ich eine Versicherung für meine Versicherung abschließen sollen.\n\nMoment, wovon rede ich denn da? IHR seid die Versicherung für die Versicherung!", sourceObjectiveStatus = "unverified-source-field" }
quests[54008] = { id = 54008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erneuerung der Versicherung", description = "Wisst Ihr, ich will einfach nur Mekkadrill und sein beklopptes Luftschiff in die Luft jagen. Natürlich wird das nicht leicht sein!\n\nIhr müsst für mich den Pannendienst retten, damit er diesen Mech instand setzen kann! Wahrscheinlich ist er in dem Allianzlager ganz in der Nähe.\n\nIn der Zwischenzeit werde ich einen Plan aushecken. Wir werden Mekkadrill eine böse Überraschung bereiten!\n\nUnd wenn ich böse sage, dann meine ich, dass wir ihn in die Luft jagen werden. Oh, und sein Luftschiff natürlich auch.", sourceObjective = "Rettet Gallywix' Pannendienst.", completion = "Die Jungs arbeiten schnell. Seht Euch dieses Ding an, es ist fast wie neu!\n\nFast.", sourceObjectiveStatus = "unverified-source-field" }
quests[54009] = { id = 54009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutiger Nebenjob", description = "Diese Nervensägen von der Allianz hier in der Gegend nehmen auf jeden Fall Befehle von Mekkadrill entgegen.\n\nDas heißt, sie müssen sterben! Und alle ihre Freunde aus Kul Tiras ebenfalls. Sie müssen wissen, dass die Horde die Nummer eins ist.\n\nUnd dass man nicht einfach den Pannendienst von jemand anderem entführt!", sourceObjective = "Tötet 15 Soldaten der Allianz und aus Kul Tiras an der Wachkuppe.", completion = "Gute Arbeit, wie Ihr diese Kerle aus dem Weg geräumt habt. Das wird ihnen eine Lehre sein, sich mit der Horde anzulegen! \n\nWie bitte? Sie haben sich nicht mit uns angelegt? Natürlich haben sie das! Die haben meine Versicherung entführt!", sourceObjectiveStatus = "unverified-source-field" }
quests[54011] = { id = 54011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nasse Sache: Aroms Wehr" }
quests[54012] = { id = 54012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch mal davongekommen", sourceObjective = "Rettet 7 gefangene Soldaten in Azsharas Speeren.", completion = "So wenige... Es wird reichen müssen. Ohne Euch wären es noch weniger.", sourceObjectiveStatus = "unverified-source-field" }
quests[54014] = { id = 54014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nasse Sache: Blutgetränkter Sand" }
quests[54015] = { id = 54015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefer hinein", description = "Ich kann diese Barriere noch für eine Weile nach unserem Aufbruch aufrechthalten, aber wir können hier nicht bleiben.\n\nDiese Soldaten sind hier nicht lange sicher.\n\nWir müssen tiefer in diesen Ort vorstoßen und eine Stellung suchen, die sich besser verteidigen lässt.", sourceObjective = "Trefft Thalyssra und Lor'themar in Nazjatar.", completion = "Vorsicht! Erregt bloß keine Aufmerksamkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[54016] = { id = 54016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azerittransport" }
quests[54017] = { id = 54017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nasse Sache: Der Kriegsbestienkral" }
quests[54018] = { id = 54018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abstieg", sourceObjective = "Trefft Euch mit Lor'themar Theron in Nazjatar.", completion = "Wir haben bereits große Verluste erlitten, {name}. Lasst uns zusammenarbeiten, um weitere zu verhindern.", sourceObjectiveStatus = "unverified-source-field" }
quests[54020] = { id = 54020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nasse Sache: Der Trübwasserübergang" }
quests[54021] = { id = 54021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die erste Arkanistin", sourceObjective = "Trefft Euch mit der Ersten Arkanistin Thalyssra in Nazjatar.", completion = "Ah, {name}. Ich bin froh, dass Ihr den Angriff überlebt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[54022] = { id = 54022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mekkadrills Schlachtpläne", description = "<Ihr findet einen Teil von Plänen, die darauf hinweisen, wo Mekkadrill sich mit seinem Luftschiff im Tiragardesund aufhält.\n\nWenn Ihr die andere Hälfte dieser Pläne finden könnt, wärt Ihr in der Lage, den Gnomkönig in einen Hinterhalt zu locken.>", sourceObjective = "Findet Mekkadrills Schlachtpläne.", progress = "Was seht Ihr Euch da an?", completion = "Was habt Ihr da?\n\n... WAS?! Das ist ja perfekt!", sourceObjectiveStatus = "unverified-source-field" }
quests[54026] = { id = 54026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeit erledigt", description = "Ich bleibe noch etwas länger hier, um sicherzustellen, dass die Peons wieder an die Arbeit gehen.\n\nIhr solltet nach Orgrimmar zurückkehren und Kommandant Dresch sagen, dass er sich um den Außenposten keine Sorgen mehr machen muss.", sourceObjective = "Kehrt zu Kommandant Dresch in der Feste Grommash in Orgrimmar zurück.", completion = "Die Peons sind zurückgekommen? Das sind wirklich gute Neuigkeiten.\n\nHoffen wir um ihretwillen, dass das nicht noch einmal vorkommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[54027] = { id = 54027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung gebannt", description = "Das sollte den Naga zu denken geben!\n\nEuch wird die Ehre zuteil, der Klingenwache Sonji zu berichten, dass die Bedrohung von Zuldazars Küste gebannt wurde.", sourceObjective = "Kehrt zu Klingenwache Sonji in der Feste Grommash in Orgrimmar zurück.", completion = "Die Bedrohung durch die Naga wurde gebannt? Ich verlasse mich diesbezüglich auf Euer Wort, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[54028] = { id = 54028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mech gegen Luftschiff", description = "Wir sind dank der Schlachtpläne, die Ihr gefunden habt, bestens vorbereitet. Sieht so aus, als ob Mekkadrill jetzt gerade nicht in seinem Luftschiff ist.\n\nDer Plan lautet wie folgt: Wir werden auf seinem Schiff gewaltiges Chaos anrichten, dann wird er vorbeikommen, um seine Freunde zu retten.\n\nStattdessen stehen wir beide auf dem Deck seines brennenden Schiffs und warten darauf, ihn zu erledigen!\n\nSteigt in den Mech, {name}, wir jagen ein Luftschiff in die Luft... und einen Gnom!", sourceObjective = "Besteigt den G.M.O.D., um ein Allianzluftschiff in die Luft zu jagen und Mekkadrill entgegenzutreten.", completion = "Was für ein Flug, hm?", sourceObjectiveStatus = "unverified-source-field" }
quests[54031] = { id = 54031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blick der Loa: Krag'wa", description = "Willkommen zurück, kleines Wesen.\n\nIch sehe, dass Talanji <einen würdigen Zeugen/eine würdige Zeugin> ausgewählt hat. Ich muss prüfen, ob Talanji bereit ist, Opfer für ihr Volk zu bringen, und ich werde über ihre Bereitschaft, die Schwachen zu schützen, urteilen. Viele große Herrscher haben diese Prüfung nicht bestanden und sind dennoch große Monarchen geworden.\n\nAber die beliebtesten unter ihnen, diejenigen mit den treuesten Anhängern, wussten darum, wie wichtig die Hingabe an ihr Volk war.\n\nIhr werdet mir bei dieser Prüfung helfen. Sprecht mit mir, wenn Ihr bereit seid.", sourceObjective = "\"Bezeugt\" Krag'was Prüfung.", completion = "Ich würde nicht zulassen, dass Euch etwas geschieht, {name}. Aber zu Eurem Glück war ein Eingreifen ja gar nicht nötig.", sourceObjectiveStatus = "unverified-source-field" }
quests[54032] = { id = 54032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blick der Loa: Pa'ku", description = "Zwei weitere Loa haben erklärt, dass sie Talanji einer Prüfung unterziehen wollen. Als Nächstes ist Pa'ku an der Reihe. Sie erwartet Euch beide am Ende dieser Stufen.\n\nIhr wisst ja, wie jähzornig sie ist und wie gern sie ihre Opfer vom Himmel fallen sieht.\n\nViel Glück, {name}.", sourceObjective = "Schließt Pa'kus Prüfung ab.", progress = "Ich bin noch nicht zufrieden, {name}.", completion = "<Pa'ku wischt sich mit ihrer Schwingenklaue eine Träne aus dem Augenwinkel.>\n\nDas war eine wundervolle Demonstration der Hingabe. Und Euer Haar sieht wundervoll aus.\n\n<Pa'ku kichert.>", sourceObjectiveStatus = "unverified-source-field" }
quests[54033] = { id = 54033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blick der Loa: Gonk", description = "Der Anführer des Rudels hat verlangt, als Nächster mit Talanji zu sprechen. Ihr findet ihn gleich die Stufen dort hoch auf der nächsten Terrasse.\n\nIch glaube nicht, dass er ebenso viel von Euch verlangt wie ich, aber seine Worte sollten für Eure Aufgabe hier von Bedeutung sein.\n\n<Krag'wa zwinkert mit einem seiner riesigen Augen.>\n\nDenkt nur nicht, dass wir nichts von Euren Vorhaben wüssten, {name}.", sourceObjective = "Schließt Gonks Prüfung ab.", progress = "Hallo noch mal, {name}.", completion = "<Der Raptorgott blickt Euch nachdenklich an.>\n\nIhr werdet Talanji an ihre Prioritäten erinnern, wenn sie die Frage beantworten muss, die ich ihr gestellt habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[54034] = { id = 54034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blick der Loa: Bwonsamdi", description = "<Pa'ku wird wieder ernst.>\n\nNormalerweise obliegt Rezan die Ehre der letzten Prüfung. Aber der Loa der Könige ist nicht mehr.\n\nDer alte Rastakhan scheint sich für einen neuen Liebling entschieden zu haben.\n\n<Pa'ku zischt höhnisch.>\n\nViel Spaß dabei. Bwonsamdi wartet auf Euch im Tempel.", sourceObjective = "Schließt Bwonsamdis Prüfung ab.", completion = "<Talanji nickt Euch zu.>\n\nDanke, dass Ihr mir die ganze Zeit zur Seite gestanden habt. Einige Entscheidungen waren leichter zu treffen als andere, aber ich fühlte mich ihnen allen gewachsen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54036] = { id = 54036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pedantischer Prozess", description = "Wie Ihr vielleicht bemerkt habt, nimmt Weinhändler Iltheux es mit seiner Weinherstellung sehr genau, aber bei der Zusammenstellung seines uralten Rezepts wurden nur die Nachtgeborenen berücksichtigt.\n\nWir brauchen etwas anderes, um die verschiedenen Geschmäcker der Horde zufriedenzustellen!\n\nSprecht mit Nomi und seht, was ihm einfällt, um mehr Würze hineinzubringen.", sourceObjective = "Sprecht mit Nomi.", completion = "Schön, Euch wiederzusehen, {name}. Ich habe bereits Verbesserungen am Rezept des Weinhändlers vorgenommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54041] = { id = 54041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Überlebenden", description = "Seht Ihr das Lager am Strand dort unten?\n\nDie Horde ist Tyrande hierher gefolgt.\n\nSie haben zweifellos eine Nachhut hier in den Schatten zurückgelassen, für den Fall, dass sie zurückkehrt.\n\nTötet sie.", sourceObjective = "Tötet 8 getarnte Todespirscher.", completion = "Die Verlassenen kämpfen immer noch, sogar nach ihrem Tod. Was treibt ihre finsteren Herzen nur an?", sourceObjectiveStatus = "unverified-source-field" }
